class FrameParser:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self._buffer = bytearray()
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("FrameParser is poisoned")
        if self._finished:
            raise ValueError("FrameParser is finished")

        buf = self._buffer
        buf.extend(chunk)

        frames: list[str] = []
        pos = 0
        total = len(buf)

        try:
            while total - pos >= 4:
                length = (
                    (buf[pos] << 24)
                    | (buf[pos + 1] << 16)
                    | (buf[pos + 2] << 8)
                    | buf[pos + 3]
                )

                if length > self.max_size:
                    raise ValueError("frame exceeds max_size")

                end = pos + 4 + length
                if end > total:
                    break

                body = buf[pos + 4:end]
                frames.append(body.decode("utf-8"))
                pos = end
        except ValueError:
            self._poisoned = True
            self._buffer.clear()
            raise ValueError("FrameParser is poisoned") from None

        if pos:
            del buf[:pos]

        return frames

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("FrameParser is poisoned")
        if self._finished:
            return None

        if self._buffer:
            self._poisoned = True
            self._buffer.clear()
            raise ValueError("partial frame")

        self._finished = True
        return None

import heapq


class _MaxId:
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value

    def __lt__(self, other):
        return self.value > other.value


def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}
    deps = {}
    reversible = {}

    for entry in migrations:
        if not isinstance(entry, dict):
            raise ValueError("invalid migration entry")
        if "id" not in entry or "deps" not in entry or "reversible" not in entry:
            raise ValueError("invalid migration entry")

        mid = entry["id"]
        dep_list = entry["deps"]
        rev = entry["reversible"]

        if not isinstance(mid, str):
            raise ValueError("invalid migration id")
        if mid in registry:
            raise ValueError("duplicate migration id")
        if not isinstance(dep_list, (list, tuple)):
            raise ValueError("invalid dependency list")

        ds = set()
        for dep in dep_list:
            if not isinstance(dep, str):
                raise ValueError("invalid dependency id")
            ds.add(dep)

        registry[mid] = entry
        deps[mid] = ds
        reversible[mid] = rev

    for mid, ds in deps.items():
        for dep in ds:
            if dep == mid:
                raise ValueError("self dependency")
            if dep not in registry:
                raise ValueError("unknown dependency")

    indegree = {mid: len(ds) for mid, ds in deps.items()}
    dependents = {mid: [] for mid in registry}
    for mid, ds in deps.items():
        for dep in ds:
            dependents[dep].append(mid)

    queue = [mid for mid in registry if indegree[mid] == 0]
    head = 0
    processed = 0
    while head < len(queue):
        cur = queue[head]
        head += 1
        processed += 1
        for nxt in dependents[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)

    if processed != len(registry):
        raise ValueError("dependency cycle")

    try:
        applied_set = set(applied)
        target_set = set(target)
    except TypeError:
        raise ValueError("invalid migration name")

    for mid in applied_set:
        if mid not in registry:
            raise ValueError("unknown applied migration")
    for mid in target_set:
        if mid not in registry:
            raise ValueError("unknown target migration")

    for mid in applied_set:
        if not deps[mid].issubset(applied_set):
            raise ValueError("applied migrations are not dependency-closed")

    desired_set = set(target_set)
    stack = list(target_set)
    while stack:
        cur = stack.pop()
        for dep in deps[cur]:
            if dep not in desired_set:
                desired_set.add(dep)
                stack.append(dep)

    to_remove = applied_set - desired_set
    for mid in to_remove:
        if not reversible[mid]:
            raise ValueError("irreversible migration removal")

    plan = []
    current_applied = set(applied_set)

    dependents_count = {mid: 0 for mid in current_applied}
    for mid in current_applied:
        for dep in deps[mid]:
            dependents_count[dep] += 1

    to_remove_remaining = set(to_remove)
    max_heap = []
    for mid in to_remove_remaining:
        if dependents_count[mid] == 0:
            heapq.heappush(max_heap, _MaxId(mid))

    while to_remove_remaining:
        if not max_heap:
            raise ValueError("cannot determine rollback order")

        item = heapq.heappop(max_heap)
        mid = item.value

        if mid not in to_remove_remaining:
            continue

        plan.append("-" + mid)
        current_applied.remove(mid)
        to_remove_remaining.remove(mid)

        for dep in deps[mid]:
            dependents_count[dep] -= 1
            if dep in to_remove_remaining and dependents_count[dep] == 0:
                heapq.heappush(max_heap, _MaxId(dep))

    missing = desired_set - current_applied

    remaining_dep_count = {}
    missing_dependents = {mid: [] for mid in missing}

    for mid in missing:
        count = 0
        for dep in deps[mid]:
            if dep in missing:
                count += 1
                missing_dependents[dep].append(mid)
        remaining_dep_count[mid] = count

    min_heap = [mid for mid in missing if remaining_dep_count[mid] == 0]
    heapq.heapify(min_heap)

    while missing:
        if not min_heap:
            raise ValueError("cannot determine forward order")

        mid = heapq.heappop(min_heap)

        if mid not in missing:
            continue

        plan.append("+" + mid)
        missing.remove(mid)
        current_applied.add(mid)

        for nxt in missing_dependents[mid]:
            if nxt in missing:
                remaining_dep_count[nxt] -= 1
                if remaining_dep_count[nxt] == 0:
                    heapq.heappush(min_heap, nxt)

    return plan

