class FrameParser:
    def __init__(self, max_size: int):
        if max_size < 0:
            raise ValueError("max_size must be non-negative")
        self._max_size = max_size
        self._buf = bytearray()
        self._pos = 0
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            raise ValueError("parser is finished")

        self._buf.extend(chunk)
        out = []
        buf = self._buf
        pos = self._pos
        max_size = self._max_size

        while True:
            available = len(buf) - pos
            if available < 4:
                break

            n = (
                (buf[pos] << 24)
                | (buf[pos + 1] << 16)
                | (buf[pos + 2] << 8)
                | buf[pos + 3]
            )

            if n > max_size:
                self._poisoned = True
                raise ValueError("frame too large")

            if available < 4 + n:
                break

            start = pos + 4
            end = start + n
            try:
                s = buf[start:end].decode("utf-8")
            except UnicodeDecodeError:
                self._poisoned = True
                raise ValueError("malformed UTF-8") from None

            out.append(s)
            pos = end

        self._pos = pos

        if pos == len(buf):
            buf.clear()
            self._pos = 0
        elif pos > 65536 and pos * 2 > len(buf):
            del buf[:pos]
            self._pos = 0

        return out

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            return None
        if self._pos != len(self._buf):
            self._poisoned = True
            raise ValueError("partial frame at finish")
        self._finished = True
        return None

from collections import OrderedDict
import heapq

def run_cache(capacity: int, operations: list[dict]) -> list:
    cap = capacity
    cache = OrderedDict()  # key -> (value, expires_at, version)
    heap = []
    seq = 0
    results = []

    for op in operations:
        t = op["t"]

        while heap and heap[0][0] <= t:
            expires_at, version, key = heapq.heappop(heap)
            entry = cache.get(key)
            if entry is not None and entry[1] == expires_at and entry[2] == version:
                del cache[key]

        if len(heap) > 2 * len(cache) + 1024:
            heap = [(entry[1], entry[2], key) for key, entry in cache.items()]
            heapq.heapify(heap)

        kind = op["op"]

        if kind == "put":
            key = op["key"]
            value = op["value"]
            ttl = op["ttl"]

            if ttl <= 0 or cap == 0:
                if key in cache:
                    del cache[key]
                results.append(None)
            else:
                seq += 1
                expires_at = t + ttl
                cache[key] = (value, expires_at, seq)
                cache.move_to_end(key)
                heapq.heappush(heap, (expires_at, seq, key))

                while len(cache) > cap:
                    cache.popitem(last=False)

                if len(heap) > 2 * len(cache) + 1024:
                    heap = [(entry[1], entry[2], key) for key, entry in cache.items()]
                    heapq.heapify(heap)

                results.append(None)

        elif kind == "get":
            key = op["key"]
            entry = cache.get(key)
            if entry is None:
                results.append(None)
            else:
                cache.move_to_end(key)
                results.append(entry[0])

        elif kind == "delete":
            key = op["key"]
            if key in cache:
                del cache[key]
                results.append(True)
            else:
                results.append(False)

        elif kind == "items":
            results.append([[key, entry[0]] for key, entry in cache.items()])

        elif kind == "resize":
            cap = op["capacity"]
            while len(cache) > cap:
                cache.popitem(last=False)

            if len(heap) > 2 * len(cache) + 1024:
                heap = [(entry[1], entry[2], key) for key, entry in cache.items()]
                heapq.heapify(heap)

            results.append(None)

        else:
            results.append(None)

    return results

def _is_int_not_bool(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_positive_int(value):
    return _is_int_not_bool(value) and value > 0


def _deep_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False

        if all(isinstance(k, str) for k in a) and all(isinstance(k, str) for k in b):
            for key, value in a.items():
                if key not in b:
                    return False
                if not _deep_equal(value, b[key]):
                    return False
            return True

        b_items = list(b.items())
        used = [False] * len(b_items)

        for a_key, a_value in a.items():
            found = False
            for i, (b_key, b_value) in enumerate(b_items):
                if used[i]:
                    continue
                if _deep_equal(a_key, b_key) and _deep_equal(a_value, b_value):
                    used[i] = True
                    found = True
                    break
            if not found:
                return False
        return True

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not _deep_equal(x, y):
                return False
        return True

    if type(a) is not type(b):
        return False

    return a == b


def replay_ledger(initial, events):
    balances = dict(initial)
    seen = {}
    results = []

    for event in events:
        event_id = event["id"]

        if event_id in seen:
            if _deep_equal(seen[event_id], event):
                results.append({"id": event_id, "status": "duplicate"})
            else:
                results.append({"id": event_id, "status": "conflict"})
            continue

        seen[event_id] = event

        moves = event.get("moves")
        expected = event.get("expected", {})

        valid = True

        if not isinstance(moves, list) or not isinstance(expected, dict):
            valid = False

        if valid:
            for move in moves:
                if not isinstance(move, list) or len(move) != 3:
                    valid = False
                    break

                source, destination, amount = move

                try:
                    if source not in balances or destination not in balances:
                        valid = False
                        break
                except TypeError:
                    valid = False
                    break

                if source == destination or not _is_positive_int(amount):
                    valid = False
                    break

        if valid:
            for account, value in expected.items():
                try:
                    if account not in balances:
                        valid = False
                        break
                except TypeError:
                    valid = False
                    break

                if not _is_int_not_bool(value):
                    valid = False
                    break

        if not valid:
            results.append({"id": event_id, "status": "invalid"})
            continue

        guarded = False
        for account, value in expected.items():
            if balances[account] != value:
                guarded = True
                break

        if guarded:
            results.append({"id": event_id, "status": "guard"})
            continue

        tentative = dict(balances)
        succeeded = True

        for source, destination, amount in moves:
            if tentative[source] < amount:
                succeeded = False
                break

            tentative[source] -= amount
            tentative[destination] += amount

        if succeeded:
            balances = tentative
            results.append({"id": event_id, "status": "applied"})
        else:
            results.append({"id": event_id, "status": "insufficient"})

    return {"balances": balances, "results": results}

from collections import OrderedDict
import heapq


def run_cache(capacity: int, operations: list[dict]) -> list:
    entries = OrderedDict()
    heap = []
    version = 0
    results = []

    def rebuild_heap():
        nonlocal heap
        heap = [(entry[1], key, entry[2]) for key, entry in entries.items()]
        heapq.heapify(heap)

    def purge(t):
        while heap and heap[0][0] <= t:
            _, key, ver = heapq.heappop(heap)
            entry = entries.get(key)
            if entry is not None and entry[2] == ver:
                del entries[key]
        if len(heap) > 2 * len(entries) + 1000:
            rebuild_heap()

    for op in operations:
        t = op["t"]
        purge(t)
        kind = op["op"]

        if kind == "put":
            key = op["key"]
            value = op["value"]
            ttl = op["ttl"]

            if ttl <= 0 or capacity == 0:
                if key in entries:
                    del entries[key]
                results.append(None)
            else:
                expires_at = t + ttl
                version += 1

                if key in entries:
                    entry = entries[key]
                    entry[0] = value
                    entry[1] = expires_at
                    entry[2] = version
                    entries.move_to_end(key)
                else:
                    entries[key] = [value, expires_at, version]

                heapq.heappush(heap, (expires_at, key, version))

                while len(entries) > capacity:
                    entries.popitem(last=False)

                results.append(None)

        elif kind == "get":
            key = op["key"]
            entry = entries.get(key)
            if entry is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(entry[0])

        elif kind == "delete":
            key = op["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)

        elif kind == "items":
            results.append([[key, entry[0]] for key, entry in entries.items()])

        elif kind == "resize":
            capacity = op["capacity"]
            while len(entries) > capacity:
                entries.popitem(last=False)
            results.append(None)

        else:
            results.append(None)

    return results

