def _parse_fixed(value):
    s = value.strip()
    if s.startswith('+'):
        s = s[1:]

    if '.' in s:
        whole, frac = s.split('.', 1)
        if whole == '':
            whole = '0'
        digits = whole + frac
        if digits == '':
            digits = '0'
        return int(digits), 10 ** len(frac)

    if s == '':
        return 0, 1
    return int(s), 1


def _round_half_up(numerator, denominator):
    return (2 * numerator + denominator) // (2 * denominator)


def _format_cents(cents):
    return f"{cents // 100}.{cents % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    rate_num, rate_den = _parse_fixed(tax_rate)
    coupon_num, coupon_den = _parse_fixed(coupon)

    lines = []
    subtotal = 0

    for item in items:
        unit_num, unit_den = _parse_fixed(item["unit"])
        qty = item["qty"]
        gross = _round_half_up(unit_num * qty * 100, unit_den)
        taxable = item["taxable"]
        lines.append((gross, taxable))
        subtotal += gross

    coupon_cents = _round_half_up(coupon_num * 100, coupon_den)
    if coupon_cents > subtotal:
        coupon_cents = subtotal

    discount_total = coupon_cents
    discounts = [0] * len(lines)

    if subtotal > 0 and discount_total > 0:
        remainders = []
        allocated = 0

        for i, (gross, _) in enumerate(lines):
            product = discount_total * gross
            base = product // subtotal
            remainder = product - base * subtotal
            discounts[i] = base
            allocated += base

            if gross > 0:
                remainders.append((remainder, i))

        remaining = discount_total - allocated

        if remaining > 0:
            remainders.sort(key=lambda pair: (-pair[0], pair[1]))
            for j in range(remaining):
                discounts[remainders[j][1]] += 1

    out_lines = []
    total_net = 0
    total_tax = 0

    for (gross, taxable), discount in zip(lines, discounts):
        net = gross - discount

        if taxable:
            tax = _round_half_up(net * rate_num, rate_den)
        else:
            tax = 0

        line_total = net + tax

        out_lines.append({
            "gross": _format_cents(gross),
            "discount": _format_cents(discount),
            "net": _format_cents(net),
            "tax": _format_cents(tax),
            "total": _format_cents(line_total),
        })

        total_net += net
        total_tax += tax

    total = total_net + total_tax

    return {
        "lines": out_lines,
        "subtotal": _format_cents(subtotal),
        "discount": _format_cents(discount_total),
        "net": _format_cents(total_net),
        "tax": _format_cents(total_tax),
        "total": _format_cents(total),
    }

import copy
import math


def _json_equal(a, b):
    if a is b:
        return True
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if a is None or b is None:
        return a is None and b is None
    a_num = isinstance(a, (int, float))
    b_num = isinstance(b, (int, float))
    if a_num or b_num:
        if not (a_num and b_num):
            return False
        if isinstance(a, float) and isinstance(b, float) and math.isnan(a) and math.isnan(b):
            return True
        return a == b
    if isinstance(a, dict) or isinstance(b, dict):
        if not (isinstance(a, dict) and isinstance(b, dict)):
            return False
        if len(a) != len(b):
            return False
        for key, value in a.items():
            if key not in b:
                return False
            if not _json_equal(value, b[key]):
                return False
        return True
    if isinstance(a, list) or isinstance(b, list):
        if not (isinstance(a, list) and isinstance(b, list)):
            return False
        if len(a) != len(b):
            return False
        for left, right in zip(a, b):
            if not _json_equal(left, right):
                return False
        return True
    return type(a) is type(b) and a == b


def _canonical_key(value):
    if value is None:
        return (0,)
    if isinstance(value, bool):
        return (1, value)
    if isinstance(value, int):
        return (2, 0, value)
    if isinstance(value, float):
        if math.isnan(value):
            return (2, 1, "nan")
        return (2, 1, repr(value))
    if isinstance(value, str):
        return (3, value)
    if isinstance(value, list):
        return (4, tuple(_canonical_key(item) for item in value))
    if isinstance(value, dict):
        items = [(_canonical_key(key), _canonical_key(item)) for key, item in value.items()]
        items.sort()
        return (5, tuple(items))
    return (6, type(value).__name__, repr(value))


def _copy_json(value):
    if isinstance(value, dict):
        return {key: _copy_json(value[key]) for key in sorted(value.keys())}
    if isinstance(value, list):
        return [_copy_json(item) for item in value]
    return copy.deepcopy(value)


def resolve_records(events: list[dict]) -> dict:
    seen = {}

    for event in events:
        event_id = event["id"]
        if event_id not in seen:
            seen[event_id] = [event, None]
            continue

        entry = seen[event_id]
        previous = entry[0]
        if not _json_equal(event, previous):
            raise ValueError("conflicting duplicate event id")

        event_key = _canonical_key(event)
        previous_key = entry[1]
        if previous_key is None:
            previous_key = _canonical_key(previous)

        if event_key < previous_key:
            entry[0] = event
            entry[1] = event_key
        else:
            entry[1] = previous_key

    deduplicated = [entry[0] for entry in seen.values()]
    ordered = sorted(
        deduplicated,
        key=lambda event: (event["ts"], event["actor"], event["id"]),
        reverse=True,
    )

    claimed = set()
    final_values = {}
    tombstone_keys = set()
    accepted = []
    rejected = []

    for event in ordered:
        writes = event["writes"]
        keys = list(writes.keys())

        if any(key in claimed for key in keys):
            rejected.append(event["id"])
            continue

        accepted.append(event["id"])
        for key in keys:
            claimed.add(key)
            value = writes[key]
            if value is None:
                tombstone_keys.add(key)
            else:
                final_values[key] = _copy_json(value)

    values = {key: final_values[key] for key in sorted(final_values.keys())}
    tombstones = sorted(tombstone_keys)

    return {
        "values": values,
        "tombstones": tombstones,
        "accepted": accepted,
        "rejected": rejected,
    }

