{"path":"parsing.py","content":"def env_int(value):
    """Parse an integer environment value.

    Recognized environment integers must be strings containing only ASCII
    decimal digits after outer whitespace is removed.  Leading zeroes are
    permitted.
    """
    if not isinstance(value, str):
        raise ValueError("environment integer must be a string")
    text = value.strip()
    if not text:
        raise ValueError("environment integer must not be empty")
    for char in text:
        if char < "0" or char > "9":
            raise ValueError("environment integer must contain ASCII digits only")
    # Avoid Python's conversion limit being triggered by a long run of
    # leading zeroes, which are harmless and explicitly allowed.
    significant = text.lstrip("0")
    if not significant:
        return 0
    return int(significant)


def env_bool(value):
    """Parse a boolean environment value."""
    if not isinstance(value, str):
        raise ValueError("environment boolean must be a string")
    text = value.strip().lower()
    if text == "true" or text == "1":
        return True
    if text == "false" or text == "0":
        return False
    raise ValueError("environment boolean must be true, false, 1, or 0")
"}

