FIELDS = {"server": ("host", "port", "tls"),
          "worker": ("count", "timeout_ms")}


def _copy_value(value):
    """Return a detached JSON-like value."""
    if isinstance(value, dict):
        return {key: _copy_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_copy_value(item) for item in value]
    return value


def _copy_section(section, values):
    if section == "tags":
        return dict(values)
    return {key: _copy_value(value) for key, value in values.items()}


def _validate_patch(patch):
    """Validate only the structure of a patch.

    Leaf value types and ranges are deliberately not checked here: a later
    layer or environment override may replace them before final validation.
    """
    if not isinstance(patch, dict):
        raise ValueError("configuration must be a dict")

    for section, values in patch.items():
        if not isinstance(section, str):
            raise ValueError("section names must be strings")
        if section not in SECTIONS:
            raise ValueError("unknown section")
        if not isinstance(values, dict):
            raise ValueError("section must be a dict")

        if section == "tags":
            for key, value in values.items():
                if not isinstance(key, str) or key == "":
                    raise ValueError("tag keys must be nonempty strings")
                if value is not None and not isinstance(value, str):
                    raise ValueError("tag values must be strings or tombstones")
        else:
            allowed = FIELDS[section]
            for key in values:
                if not isinstance(key, str) or key not in allowed:
                    raise ValueError("unknown field in section")


def merge_config(current, patch):
    """Merge a validated structure into current without aliasing input data."""
    _validate_patch(patch)

    result = {}
    for section in SECTIONS:
        if section in current:
            values = current[section]
            if not isinstance(values, dict):
                raise ValueError("current section must be a dict")
            result[section] = _copy_section(section, values)
        else:
            result[section] = {}

    for section, values in patch.items():
        if section == "tags":
            tags = result["tags"]
            for key, value in values.items():
                if value is None:
                    if key in tags:
                        del tags[key]
                else:
                    tags[key] = value
        else:
            target = result[section]
            for key, value in values.items():
                target[key] = _copy_value(value)

    return result
