{"path": "overlay.py", "content": """"Structural validation and overlay merging for configuration dictionaries."""

_SECTIONS = ("server", "worker", "tags")
_SECTION_FIELDS = {
    "server": ("host", "port", "tls"),
    "worker": ("count", "timeout_ms"),
}


def merge_config(current, patch):
    """Return a detached config with ``patch`` merged into ``current``.

    Structural errors, unknown keys, and invalid tag keys/values are rejected
    immediately.  Leaf value types and ranges are intentionally not checked
    here: a later overlay may repair an intermediate value.
    """
    if not isinstance(patch, dict):
        raise ValueError("configuration must be a dict")

    # Start with fresh dictionaries so neither inputs nor defaults are aliased.
    result = {
        "server": dict(current["server"]),
        "worker": dict(current["worker"]),
        "tags": dict(current["tags"]),
    }

    for section, values in patch.items():
        if not isinstance(section, str) or section not in _SECTIONS:
            raise ValueError("unknown configuration section")
        if not isinstance(values, dict):
            raise ValueError("configuration section must be a dict")

        if section == "tags":
            tags = result["tags"]
            for key, value in values.items():
                if not isinstance(key, str) or key == "":
                    raise ValueError("tag key must be a nonempty string")
                if value is None:
                    if key in tags:
                        del tags[key]
                elif isinstance(value, str):
                    tags[key] = value
                else:
                    raise ValueError("tag value must be a string or tombstone")
            continue

        allowed = _SECTION_FIELDS[section]
        destination = result[section]
        for key, value in values.items():
            if not isinstance(key, str) or key not in allowed:
                raise ValueError("unknown configuration field")
            destination[key] = value

    return result
