    if not isinstance(patch, dict):
        raise ValueError("config must be a dict")
    for section, values in patch.items():
        if not isinstance(section, str):
            raise ValueError("config keys must be strings")
        if section not in ("server", "worker", "tags"):
            raise ValueError("unknown section")
        if not isinstance(values, dict):
            raise ValueError("section must be a dict")

        if section == "server":
            for key in values:
                if not isinstance(key, str) or key not in ("host", "port", "tls"):
                    raise ValueError("unknown server field")
        elif section == "worker":
            for key in values:
                if not isinstance(key, str) or key not in ("count", "timeout_ms"):
                    raise ValueError("unknown worker field")
        else:
            for key, value in values.items():
                if not isinstance(key, str) or key == "":
                    raise ValueError("tag keys must be nonempty strings")
                if value is not None and not isinstance(value, str):
                    raise ValueError("tag values must be strings or tombstones")


def _copy_config(config):
    result = {}
    for key, value in config.items():
        if isinstance(value, dict):
            result[key] = dict(value)
        else:
            result[key] = value
    return result


def merge_config(current, patch):
    if not isinstance(current, dict):
        raise ValueError("config must be a dict")
    _validate_patch(patch)

    result = _copy_config(current)
    for section, values in patch.items():
        if section == "tags":
            tags = result.get("tags")
            if not isinstance(tags, dict):
                tags = {}
            for key, value in values.items():
                if value is None:
                    if key in tags:
                        del tags[key]
                else:
                    tags[key] = value
            result["tags"] = tags
        else:
            section_values = result.get(section)
            if not isinstance(section_values, dict):
