def replay_ledger(initial: dict[str, int], events: list[dict]) -> dict:
    balances = dict(initial)
    seen = {}
    results = []

    for event in events:
        event_id = event["id"]

        if event_id in seen:
            if _deep_equal(seen[event_id], event):
                results.append({"id": event_id, "status": "duplicate"})
            else:
                results.append({"id": event_id, "status": "conflict"})
            continue

        seen[event_id] = event

        moves = event.get("moves")
        valid = True

        if not isinstance(moves, list):
            valid = False
        else:
            for move in moves:
                if not isinstance(move, list) or len(move) != 3:
                    valid = False
                    break

                src, dst, amount = move

                if not (
                    isinstance(amount, int)
                    and not isinstance(amount, bool)
                    and amount > 0
                ):
                    valid = False
                    break

                try:
                    if src not in balances or dst not in balances:
                        valid = False
                        break
                except TypeError:
                    valid = False
                    break

                if src == dst:
                    valid = False
                    break

        has_expected = "expected" in event
        expected = event.get("expected", {}) if has_expected else {}

        if valid and has_expected:
            if not isinstance(expected, dict):
                valid = False
            else:
                for key, value in expected.items():
                    try:
                        if key not in balances:
                            valid = False
                            break
                    except TypeError:
                        valid = False
                        break

                    if not (isinstance(value, int) and not isinstance(value, bool)):
                        valid = False
                        break

        if not valid:
            results.append({"id": event_id, "status": "invalid"})
            continue

        if has_expected:
            expected = event["expected"]
        else:
            expected = {}

        guard_failed = False
        for key, value in expected.items():
            if balances[key] != value:
                guard_failed = True
                break

        if guard_failed:
            results.append({"id": event_id, "status": "guard"})
            continue

        tentative = balances.copy()
        insufficient = False

        for src, dst, amount in moves:
            if tentative[src] < amount:
                insufficient = True
                break

            tentative[src] -= amount
            tentative[dst] += amount

        if insufficient:
            results.append({"id": event_id, "status": "insufficient"})
        else:
            balances = tentative
            results.append({"id": event_id, "status": "applied"})

    return {"balances": balances, "results": results}

