import codecs
import re
import decimal


class SSEParser:
    _LINE_RE = re.compile(r'\r\n|\r|\n')

    def __init__(self):
        self._decoder = codecs.getincrementaldecoder('utf-8')('replace')
        self._at_start = True
        self._after_cr = False
        self._line_parts = []
        self._data_fields = None
        self._event = ""
        self._id = ""
        self._retry = None
        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed after finish")
        text = self._decoder.decode(chunk, final=False)
        return self._process_text(text)

    def finish(self) -> list[dict]:
        if self._finished:
            return []
        self._finished = True
        events = []
        text = self._decoder.decode(b'', final=True)
        events.extend(self._process_text(text))
        if self._line_parts:
            line = ''.join(self._line_parts)
            self._line_parts.clear()
            self._process_line(line, events)
        self._data_fields = None
        self._event = ""
        return events

    def _process_text(self, text: str) -> list[dict]:
        events = []
        if not text:
            return events

        if self._at_start:
            if text[0] == '\ufeff':
                text = text[1:]
            self._at_start = False
            if not text:
                return events

        if self._after_cr:
            if text[0] == '\n':
                text = text[1:]
            self._after_cr = False
            if not text:
                return events

        last = 0
        for m in self._LINE_RE.finditer(text):
            seg = text[last:m.start()]
            if seg:
                self._line_parts.append(seg)
            line = ''.join(self._line_parts)
            self._line_parts.clear()
            self._process_line(line, events)
            term = m.group()
            self._after_cr = (term == '\r' and m.end() == len(text))
            last = m.end()

        if last < len(text):
            self._line_parts.append(text[last:])

        return events

    def _process_line(self, line: str, events: list[dict]) -> None:
        if line == "":
            if self._data_fields is not None:
                data = "\n".join(self._data_fields)
                event = self._event if self._event != "" else "message"
                events.append({
                    "event": event,
                    "data": data,
                    "id": self._id,
                    "retry": self._retry,
                })
            self._data_fields = None
            self._event = ""
            return

        if line.startswith(":"):
            return

        idx = line.find(":")
        if idx == -1:
            field = line
            value = ""
        else:
            field = line[:idx]
            value = line[idx + 1:]
            if value.startswith(" "):
                value = value[1:]

        if field == "data":
            if self._data_fields is None:
                self._data_fields = []
            self._data_fields.append(value)
        elif field == "event":
            self._event = value
        elif field == "id":
            if "\x00" not in value:
                self._id = value
        elif field == "retry":
            if value and all('0' <= c <= '9' for c in value):
                self._retry = self._parse_retry(value)

    @staticmethod
    def _parse_retry(value: str) -> int:
        try:
            return int(value)
        except ValueError:
            return int(decimal.Decimal(value))
