import codecs
import re

_LINE_BREAK_RE = re.compile(r"[\r\n]")


class SSEParser:
    def __init__(self):
        self._decoder = codecs.getincrementaldecoder("utf-8")("replace")
        self._at_start = True
        self._pending_cr = False
        self._line_parts = []

        self._data = []
        self._data_seen = False
        self._event = ""
        self._id = ""
        self._retry = None

        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")
        if not chunk:
            return []

        out = []
        text = self._decoder.decode(chunk, final=False)
        self._process_text(text, out)
        return out

    def finish(self) -> list[dict]:
        if self._finished:
            return []

        self._finished = True
        out = []

        tail = self._decoder.decode(b"", final=True)
        self._process_text(tail, out)

        if self._line_parts:
            line = "".join(self._line_parts)
            self._line_parts.clear()
            if line:
                self._process_line(line, out)

        return out

    def _process_text(self, text: str, out: list[dict]) -> None:
        if not text:
            return

        if self._at_start:
            self._at_start = False
            if text[0] == "\ufeff":
                text = text[1:]
                if not text:
                    return

        n = len(text)
        i = 0

        if self._pending_cr:
            self._pending_cr = False
            if text[0] == "\n":
                i = 1

        while i < n:
            match = _LINE_BREAK_RE.search(text, i)
            if match is None:
                self._line_parts.append(text[i:])
                break

            pos = match.start()
            if pos > i:
                self._line_parts.append(text[i:pos])

            self._emit_line(out)

            if text[pos] == "\r":
                i = pos + 1
                if i < n:
                    if text[i] == "\n":
                        i += 1
                else:
                    self._pending_cr = True
            else:
                i = pos + 1

    def _emit_line(self, out: list[dict]) -> None:
        line = "".join(self._line_parts)
        self._line_parts.clear()
        self._process_line(line, out)

    def _process_line(self, line: str, out: list[dict]) -> None:
        if line == "":
            if self._data_seen:
                out.append({
                    "event": self._event if self._event != "" else "message",
                    "data": "\n".join(self._data),
                    "id": self._id,
                    "retry": self._retry,
                })

            self._data.clear()
            self._data_seen = False
            self._event = ""
            return

        if line[0] == ":":
            return

        colon = line.find(":")
        if colon == -1:
            field = line
            value = ""
        else:
            field = line[:colon]
            value = line[colon + 1:]
            if value.startswith(" "):
                value = value[1:]

        if field == "data":
            self._data.append(value)
            self._data_seen = True
        elif field == "event":
            self._event = value
        elif field == "id":
            if "\x00" not in value:
                self._id = value
        elif field == "retry":
            if self._is_ascii_digits(value):
                self._retry = self._parse_decimal(value)

    @staticmethod
    def _is_ascii_digits(value: str) -> bool:
        if not value:
            return False
        for ch in value:
            if ch < "0" or ch > "9":
                return False
        return True

    @staticmethod
    def _parse_decimal(value: str) -> int:
        n = 0
        for i in range(0, len(value), 1000):
            chunk = value[i:i + 1000]
            n = n * (10 ** len(chunk)) + int(chunk)
        return n

