class FrameParser:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self._buffer = bytearray()
        self._poisoned = False
        self._finished = False

    def feed(self, chunk: bytes) -> list[str]:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            raise ValueError("parser has already been finished")

        self._buffer.extend(chunk)
        buf = self._buffer
        total = len(buf)
        pos = 0
        frames: list[str] = []

        while total - pos >= 4:
            n = (
                (buf[pos] << 24)
                | (buf[pos + 1] << 16)
                | (buf[pos + 2] << 8)
                | buf[pos + 3]
            )

            if n > self.max_size:
                self._poisoned = True
                self._buffer.clear()
                raise ValueError("frame body length exceeds max_size")

            end = pos + 4 + n
            if total < end:
                break

            if n == 0:
                text = ""
            else:
                body_start = pos + 4
                try:
                    text = buf[body_start:end].decode("utf-8")
                except UnicodeDecodeError as exc:
                    self._poisoned = True
                    self._buffer.clear()
                    raise ValueError("frame body is not valid UTF-8") from exc

            frames.append(text)
            pos = end

        if pos:
            del self._buffer[:pos]

        return frames

    def finish(self) -> None:
        if self._poisoned:
            raise ValueError("parser is poisoned")
        if self._finished:
            return None

        if self._buffer:
            self._poisoned = True
            self._buffer.clear()
            raise ValueError("incomplete frame at finish")

        self._finished = True
        return None

