class _MaxStr:
    __slots__ = ('s',)
    def __init__(self, s):
        self.s = s
    def __lt__(self, other):
        return self.s > other.s

def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}
    for entry in migrations:
        mid = entry['id']
        if mid in registry:
            raise ValueError("duplicate migration id")
        registry[mid] = entry

    deps = {}
    reversible = {}
    for mid, entry in registry.items():
        dset = set()
        for d in entry['deps']:
            if d == mid:
                raise ValueError("self dependency")
            if d not in registry:
                raise ValueError("unknown dependency")
            dset.add(d)
        deps[mid] = dset
        reversible[mid] = entry['reversible']

    indeg = {mid: len(deps[mid]) for mid in registry}
    dependents = {mid: [] for mid in registry}
    for mid, dset in deps.items():
        for d in dset:
            dependents[d].append(mid)

    stack = [mid for mid, deg in indeg.items() if deg == 0]
    processed = 0
    while stack:
        x = stack.pop()
        processed += 1
        for y in dependents[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                stack.append(y)
    if processed != len(registry):
        raise ValueError("cycle in registry")

    applied_set = set()
    for mid in applied:
        if mid not in registry:
            raise ValueError("unknown applied migration")
        applied_set.add(mid)

    target_set = set()
    for mid in target:
        if mid not in registry:
            raise ValueError("unknown target migration")
        target_set.add(mid)

    for mid in applied_set:
        for d in deps[mid]:
            if d not in applied_set:
                raise ValueError("applied set is not dependency-closed")

    desired = set()
    stack = list(target_set)
    while stack:
        x = stack.pop()
        if x in desired:
            continue
        desired.add(x)
        for d in deps[x]:
            if d not in desired:
                stack.append(d)

    outside = applied_set - desired
    for mid in outside:
        if not reversible[mid]:
            raise ValueError("irreversible migration must be removed")

    plan = []

    outdeg = {mid: 0 for mid in outside}
    for y in outside:
        for d in deps[y]:
            if d in outside:
                outdeg[d] += 1

    heap = []
    for mid, deg in outdeg.items():
        if deg == 0:
            heapq.heappush(heap, _MaxStr(mid))

    remaining_outside = set(outside)
    while heap:
        item = heapq.heappop(heap)
        x = item.s
        if x not in remaining_outside:
            continue
        plan.append('-' + x)
        remaining_outside.remove(x)
        for d in deps[x]:
            if d in remaining_outside:
                outdeg[d] -= 1
                if outdeg[d] == 0:
                    heapq.heappush(heap, _MaxStr(d))

    if remaining_outside:
        raise ValueError("cannot rollback")

    applied_current = set(applied_set)
    applied_current -= outside
    missing = desired - applied_current

    indeg2 = {mid: 0 for mid in missing}
    for mid in missing:
        for d in deps[mid]:
            if d in missing:
                indeg2[mid] += 1

    heap2 = [mid for mid, deg in indeg2.items() if deg == 0]
    heapq.heapify(heap2)

    while heap2:
        x = heapq.heappop(heap2)
        plan.append('+' + x)
        for y in dependents[x]:
            if y in missing:
                indeg2[y] -= 1
                if indeg2[y] == 0:
                    heapq.heappush(heap2, y)

    return plan

