                raise ValueError("invalid dependency")
            if dep not in seen:
                seen.add(dep)
                deps.append(dep)

        registry[mid] = (tuple(deps), bool(reversible))

    for mid, (deps, _) in registry.items():
        for dep in deps:
            if dep == mid:
                raise ValueError("self dependency")
            if dep not in registry:
                raise ValueError("unknown dependency")

    color = {mid: 0 for mid in registry}
    for start in registry:
        if color[start] != 0:
            continue

        color[start] = 1
        stack = [(start, 0)]

        while stack:
            node, idx = stack[-1]
            deps = registry[node][0]

            if idx < len(deps):
                dep = deps[idx]
                stack[-1] = (node, idx + 1)

                if color[dep] == 1:
                    raise ValueError("dependency cycle")
                if color[dep] == 0:
                    color[dep] = 1
                    stack.append((dep, 0))
            else:
                color[node] = 2
                stack.pop()

