    for mid in applied:
        if not isinstance(mid, str) or mid not in registry:
            raise ValueError("unknown applied migration")
        applied_set.add(mid)

    target_set = set()
    for mid in target:
        if not isinstance(mid, str) or mid not in registry:
            raise ValueError("unknown target migration")
        target_set.add(mid)

    for mid in applied_set:
        for dep in registry[mid][0]:
            if dep not in applied_set:
                raise ValueError("applied migrations are not dependency-closed")

    desired = set(target_set)
    stack = list(target_set)
    while stack:
        mid = stack.pop()
        for dep in registry[mid][0]:
            if dep not in desired:
                desired.add(dep)
                stack.append(dep)

    dependents = {mid: [] for mid in registry}
    for mid, (deps, _) in registry.items():
        for dep in deps:
            dependents[dep].append(mid)

    removal_set = applied_set - desired

