        blocked = {}
        heap = []

        for mid in removal_set:
            count = 0
            for dependent in dependents[mid]:
                if dependent in current:
                    count += 1
            blocked[mid] = count
            if count == 0:
                heapq.heappush(heap, _MaxKey(mid))

        while heap:
            item = heapq.heappop(heap)
            mid = item.key

            if mid not in current:
                continue

            removed_steps.append("-" + mid)
            current.remove(mid)

            for dep in registry[mid][0]:
