            if mid in current:
                raise ValueError("unable to determine rollback order")

    missing_set = desired - current
    forward_steps = []

    if missing_set:
        counts = {}
        heap = []

        for mid in missing_set:
            count = 0
            for dep in registry[mid][0]:
                if dep not in current:
                    count += 1
            counts[mid] = count
