        while heap:
            mid = heapq.heappop(heap)

            if mid in current:
                continue

            current.add(mid)
            forward_steps.append("+" + mid)

            for dependent in dependents[mid]:
                if dependent in missing_set and dependent not in current:
                    counts[dependent] -= 1
                    if counts[dependent] == 0:
                        heapq.heappush(heap, dependent)

        for mid in missing_set:
            if mid not in current:
