        res = None
        while node is not None:
            if node.start <= pos:
                res = node
                node = node.right
            else:
                node = node.left
        return res

    def find_succ(self, pos):
        node = self.root
        res = None
        while node is not None:
            if node.start >= pos:
                res = node
                node = node.left
            else:
                node = node.right
        return res

    def add_interval(self, a, b):
        if a >= b:
            return
        pred = self.find_pred(a)
        if pred is not None and pred.end >= a:
            a = min(a, pred.start)
            b = max(b, pred.end)
            self.delete(pred.start)
        while True:
            succ = self.find_succ(a)
            if succ is None or succ.start > b:
                break
            b = max(b, succ.end)
            self.delete(succ.start)
        self.insert_interval(a, b)

    def allocate_from_free(self, start, size):
        end = start + size
        pred = self.find_pred(start)
        if pred is None or pred.end < end:
            return False
        a = pred.start
        b = pred.end
        self.delete(a)
        if a < start:
            self.insert_interval(a, start)
        if end < b:
