    def find_first_fit(self, size, align):
        node = self.root
        stack = []
        while stack or node is not None:
            while node is not None:
                if node.max_len < size:
                    node = None
                    break
                stack.append(node)
                node = node.left
            if not stack:
                break
            node = stack.pop()
            a = node.start
            b = node.end
            if b - a >= size:
                cand = ((a + align - 1) // align) * align
                if cand + size <= b:
                    return (cand, a, b)
            node = node.right
        return None

