def allocate_intervals(limit: int, operations: list[dict]) -> dict:
    treap = _Treap(limit)
    active = {}
    results = []

    for op in operations:
        typ = op.get("op")

        if typ == "alloc":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ in active:
                results.append(None)
                continue

            fit = treap.find_first_fit(size, align)
            if fit is None:
                results.append(None)
            else:
                start, a, b = fit
                treap.delete(a)
                if a < start:
                    treap.insert_interval(a, start)
                end = start + size
                if end < b:
                    treap.insert_interval(end, b)
                active[id_] = (start, size)
                results.append(start)

        elif typ == "resize":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ not in active:
                results.append(None)
                continue

            old_start, old_size = active[id_]
            keep = False

            if old_start % align == 0:
                if size <= old_size:
                    keep = True
                else:
                    pos = old_start + old_size
                    pred = treap.find_pred(pos)
                    if pred is not None and pred.end >= old_start + size:
                        keep = True

            if keep:
                if size < old_size:
                    treap.add_interval(old_start + size, old_start + old_size)
                elif size > old_size:
                    treap.allocate_from_free(old_start + old_size, size - old_size)
                active[id_] = (old_start, size)
                results.append(old_start)
            else:
                treap.add_interval(old_start, old_start + old_size)
                fit = treap.find_first_fit(size, align)
                if fit is None:
                    treap.allocate_from_free(old_start, old_size)
                    results.append(None)
                else:
                    start, a, b = fit
                    treap.delete(a)
                    if a < start:
                        treap.insert_interval(a, start)
                    end = start + size
                    if end < b:
                        treap.insert_interval(end, b)
                    active[id_] = (start, size)
                    results.append(start)

        elif typ == "free":
            id_ = op["id"]
            if id_ not in active:
                results.append(False)
            else:
                s, sz = active.pop(id_)
                treap.add_interval(s, s + sz)
                results.append(True)

        else:
            results.append(None)

    allocations = {id_: [start, size] for id_, (start, size) in active.items()}
    return {"results": results, "allocations": allocations, "free": treap.to_list()}

