    alloc_root = None
    allocations = {}
    results = []

    for op in operations:
        kind = op.get("op")

        if kind == "alloc":
            ident = op["id"]
            size = op["size"]
            align = op["align"]

            if ident in allocations:
                results.append(None)
                continue

            if free_root is None:
