                free_root = f_remove(free_root, old_start, old_start + old_size)
                results.append(None)
                continue

            free_root = f_remove(free_root, new_start, new_start + size)
            alloc_root = a_delete(alloc_root, old_start)
            alloc_root = a_insert(alloc_root, AllocNode(new_start, next_rand()))
            allocations[ident] = [new_start, size]
            results.append(new_start)

        elif kind == "free":
            ident = op["id"]

            if ident not in allocations:
                results.append(False)
                continue

            old_start, old_size = allocations.pop(ident)
            free_root = f_add(free_root, old_start, old_start + old_size)
            alloc_root = a_delete(alloc_root, old_start)
            results.append(True)

        else:
            results.append(None)

