    stack = []
    node = free_root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        free_list.append([node.start, node.end])
        node = node.right

    alloc_out = {}
    for ident in sorted(allocations):
        val = allocations[ident]
        alloc_out[ident] = [val[0], val[1]]

    return {
        "results": results,
        "allocations": alloc_out,
        "free": free_list,
    }
