def schedule_jobs(jobs: list[dict], workers: int) -> list[dict]:
    if not jobs:
        return []
    if not isinstance(workers, int) or isinstance(workers, bool) or workers <= 0:
        raise ValueError("workers must be a positive integer")

    job_by_id = {}
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError("job must be a dict")
        try:
            jid = job["id"]
            duration = job["duration"]
            priority = job["priority"]
            deps = job["deps"]
        except KeyError:
            raise ValueError("missing job field")

        if not isinstance(jid, str):
            raise ValueError("job id must be a string")
        if jid in job_by_id:
            raise ValueError("duplicate job id")
        if not isinstance(duration, int) or isinstance(duration, bool) or duration <= 0:
            raise ValueError("duration must be a positive integer")
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError("priority must be an integer")
        if not isinstance(deps, list):
            raise ValueError("deps must be a list")

        dep_set = set()
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("dependency must be a string")
            dep_set.add(d)

        job_by_id[jid] = {
            "id": jid,
            "duration": duration,
            "priority": priority,
            "deps": dep_set,
        }

    for jid, info in job_by_id.items():
        for d in info["deps"]:
            if d == jid:
                raise ValueError("self dependency")
            if d not in job_by_id:
                raise ValueError("unknown dependency")

    dependents = {jid: [] for jid in job_by_id}
    indegree = {jid: len(info["deps"]) for jid, info in job_by_id.items()}
    for jid, info in job_by_id.items():
        for d in info["deps"]:
            dependents[d].append(jid)

    queue = [jid for jid in job_by_id if indegree[jid] == 0]
    idx = 0
    while idx < len(queue):
        jid = queue[idx]
        idx += 1
        for dep in dependents[jid]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                queue.append(dep)

    if len(queue) != len(job_by_id):
        raise ValueError("cycle detected")

    dep_count = {jid: len(info["deps"]) for jid, info in job_by_id.items()}
    ready = []
    for jid, info in job_by_id.items():
        if dep_count[jid] == 0:
            heapq.heappush(ready, (-info["priority"], jid))

    free = list(range(min(workers, len(job_by_id))))
    heapq.heapify(free)
    busy = []
    actions = []
    current_time = 0
    started_count = 0
    total = len(job_by_id)

    while started_count < total:
        while busy and busy[0][0] == current_time:
            end, worker, jid = heapq.heappop(busy)
            heapq.heappush(free, worker)
            for dep in dependents[jid]:
                dep_count[dep] -= 1
                if dep_count[dep] == 0:
                    info = job_by_id[dep]
                    heapq.heappush(ready, (-info["priority"], dep))

        while free and ready:
            neg_priority, jid = heapq.heappop(ready)
            worker = heapq.heappop(free)
            info = job_by_id[jid]
            start = current_time
            end = start + info["duration"]
            actions.append({"id": jid, "start": start, "end": end, "worker": worker})
            started_count += 1
            heapq.heappush(busy, (end, worker, jid))

        if started_count == total:
            break
        if not busy:
            raise ValueError("unable to schedule")
        current_time = busy[0][0]

    return actions

