            if dep not in job_map:
                raise ValueError("unknown dependency")
            seen.add(dep)
        dep_count[jid] = len(seen)
        for dep in seen:
            dependents[dep].append(jid)

    temp_count = dict(dep_count)
    queue = [jid for jid in job_map if temp_count[jid] == 0]
    head = 0
    processed = 0

    while head < len(queue):
        jid = queue[head]
        head += 1
        processed += 1
        for dependent in dependents[jid]:
            temp_count[dependent] -= 1
            if temp_count[dependent] == 0:
                queue.append(dependent)

    if processed != len(job_map):
        raise ValueError("cycle")

    ready = []
    for jid in job_map:
        if dep_count[jid] == 0:
            heapq.heappush(ready, (-job_map[jid]["priority"], jid))

    n = len(job_map)
    free_workers = list(range(min(workers, n)))
    heapq.heapify(free_workers)

    running = []
    actions = []

    def assign_ready(time: int) -> None:
        while ready and free_workers:
            _, jid = heapq.heappop(ready)
            worker = heapq.heappop(free_workers)
            job = job_map[jid]
            end = time + job["duration"]
            actions.append({
                "id": jid,
                "start": time,
                "end": end,
                "worker": worker,
            })
            heapq.heappush(running, (end, jid, worker))

    assign_ready(0)

    while running:
        t = running[0][0]

        while running and running[0][0] == t:
            _, jid, worker = heapq.heappop(running)
            heapq.heappush(free_workers, worker)

            for dependent in dependents[jid]:
                dep_count[dependent] -= 1
                if dep_count[dependent] == 0:
                    heapq.heappush(
                        ready,
                        (-job_map[dependent]["priority"], dependent),
                    )

