def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    def parse_fixed(s: str):
        s = s.strip()
        if not s:
            return 0, 1

        sign = 1
        if s[0] == '+':
            s = s[1:]
        elif s[0] == '-':
            sign = -1
            s = s[1:]

        if not s:
            return 0, 1

        if '.' in s:
            whole, frac = s.split('.', 1)
        else:
            whole, frac = s, ''

        if whole == '':
            whole = '0'

        if frac:
            num = int(whole + frac)
            den = 10 ** len(frac)
        else:
            num = int(whole)
            den = 1

        return sign * num, den

    def round_half_up(n: int, d: int) -> int:
        if n >= 0:
            return (2 * n + d) // (2 * d)
        return -((2 * (-n) + d) // (2 * d))

    def cents_to_str(c: int) -> str:
        return f"{c // 100}.{c % 100:02d}"

    n = len(items)

    grosses = [0] * n
    for i, item in enumerate(items):
        unit_num, unit_den = parse_fixed(item["unit"])
        qty = item["qty"]
        grosses[i] = round_half_up(unit_num * qty * 100, unit_den)

    subtotal = sum(grosses)

    coupon_num, coupon_den = parse_fixed(coupon)
    coupon_cents = round_half_up(coupon_num * 100, coupon_den)
    if coupon_cents < 0:
        coupon_cents = 0

    if subtotal > 0:
        discount_total = coupon_cents if coupon_cents < subtotal else subtotal
    else:
        discount_total = 0

    discounts = [0] * n

    if subtotal > 0 and discount_total > 0:
        remainders = []
        floor_sum = 0

        for i, gross in enumerate(grosses):
            if gross <= 0:
                continue

            product = discount_total * gross
            q, r = divmod(product, subtotal)
            discounts[i] = q
            floor_sum += q
            remainders.append((-r, i))

        remaining = discount_total - floor_sum
        if remaining:
            remainders.sort()
            for k in range(remaining):
                idx = remainders[k][1]
                discounts[idx] += 1

    rate_num, rate_den = parse_fixed(tax_rate)

    lines = []
    total_net = 0
    total_tax = 0

    for i, item in enumerate(items):
        gross = grosses[i]
        discount = discounts[i]
        net = gross - discount

        if item["taxable"]:
            tax = round_half_up(net * rate_num, rate_den)
        else:
            tax = 0

        line_total = net + tax

        lines.append({
            "gross": cents_to_str(gross),
            "discount": cents_to_str(discount),
            "net": cents_to_str(net),
            "tax": cents_to_str(tax),
            "total": cents_to_str(line_total),
        })

        total_net += net
        total_tax += tax

    total = total_net + total_tax

    return {
        "lines": lines,
        "subtotal": cents_to_str(subtotal),
        "discount": cents_to_str(discount_total),
        "net": cents_to_str(total_net),
        "tax": cents_to_str(total_tax),
        "total": cents_to_str(total),
    }

def _parse_decimal(s: str):
    s = s.strip()
    if not s:
        return 0, 0
    sign = 1
    if s[0] == '+':
        s = s[1:]
    elif s[0] == '-':
        sign = -1
        s = s[1:]
    if '.' in s:
        int_part, frac_part = s.split('.', 1)
    else:
        int_part, frac_part = s, ''
    value = 0
    for ch in int_part:
        if '0' <= ch <= '9':
            value = value * 10 + (ord(ch) - 48)
    for ch in frac_part:
        if '0' <= ch <= '9':
            value = value * 10 + (ord(ch) - 48)
    value *= sign
    scale = len(frac_part)
    if value == 0:
        return 0, 0
    while scale > 0 and value % 10 == 0:
        value //= 10
        scale -= 1
    return value, scale


