    discount_total = min(coupon_cents, subtotal)

    bases = [0] * len(grosses)
    if subtotal > 0 and discount_total > 0:
        sum_base = 0
        rems = [0] * len(grosses)
        for i, g in enumerate(grosses):
            if g == 0:
                continue
            num = discount_total * g
            base = num // subtotal
            rem = num % subtotal
            bases[i] = base
            rems[i] = rem
            sum_base += base

        remaining = discount_total - sum_base
        order = sorted(range(len(grosses)), key=lambda i: (-rems[i], i))
        for i in order:
            if remaining <= 0:
                break
            if grosses[i] == 0:
                continue
            bases[i] += 1
            remaining -= 1

        if remaining > 0:
            for i, g in enumerate(grosses):
                if remaining <= 0:
                    break
                if g > 0:
                    bases[i] += 1
                    remaining -= 1

    discounts = bases

    lines = []
    total_tax = 0
    for i, g in enumerate(grosses):
        d = discounts[i]
        net = g - d
        if items[i]["taxable"]:
