        else:
            tax = 0
        total_tax += tax
        total = net + tax
        lines.append({
            "gross": _cents_to_str(g),
            "discount": _cents_to_str(d),
            "net": _cents_to_str(net),
            "tax": _cents_to_str(tax),
            "total": _cents_to_str(total),
        })

    net_total = subtotal - discount_total
    total = net_total + total_tax
    return {
        "lines": lines,
        "subtotal": _cents_to_str(subtotal),
        "discount": _cents_to_str(discount_total),
        "net": _cents_to_str(net_total),
        "tax": _cents_to_str(total_tax),
        "total": _cents_to_str(total),
    }

