        return None

    if key < root.start:
        root.left = _erase(root.left, key)
        _update(root)
        return root

    if key > root.start:
        root.right = _erase(root.right, key)
        _update(root)
        return root

    return _merge(root.left, root.right)


class _FreeSet:
    __slots__ = ("root", "counter")

    def __init__(self, limit):
        self.root = None
        self.counter = 0
        if limit > 0:
            self.root = _Node(0, limit, self._next_priority())

    def _next_priority(self):
        mask = (1 << 64) - 1
        self.counter = (self.counter + 0x9E3779B97F4A7C15) & mask
        x = self.counter
        x = ((x ^ (x >> 30)) * 0xBF58476D1CE4E5B9) & mask
        x = ((x ^ (x >> 27)) * 0x94D049BB133111EB) & mask
        x = x ^ (x >> 31)
        return x

    def _find_le(self, root, key):
        result = None
        while root is not None:
            if root.start <= key:
                result = root
                root = root.right
            else:
                root = root.left
        return result

    def _find_ge(self, root, key):
        result = None
        while root is not None:
            if root.start >= key:
                result = root
                root = root.left
            else:
                root = root.right
        return result

    def containing(self, address):
        node = self._find_le(self.root, address)
        if node is not None and node.start <= address < node.end:
            return node
        return None

    def _find_gap(self, node, minimum_end, size):
        if node is None or node.max_end < minimum_end or node.max_len < size:
            return None

        if node.left is not None:
            found = self._find_gap(node.left, minimum_end, size)
            if found is not None:
                return found

        if node.end >= minimum_end and node.end - node.start >= size:
            return node

        if node.right is not None:
            return self._find_gap(node.right, minimum_end, size)

        return None

    def query(self, size, align):
        root = self.root
        if root is None or root.max_len < size:
            return None

        candidate = 0

        while True:
            gap = self._find_gap(root, candidate, size)
            if gap is None:
                return None

            a = gap.start
            b = gap.end

            if a > candidate:
                candidate = ((a + align - 1) // align) * align
            else:
                if candidate + size <= b:
                    return candidate
                candidate = (b // align + 1) * align

    def add_interval(self, start, end):
        if end <= start:
            return

        root = self.root

        pred = self._find_le(root, start)
        if pred is not None and pred.end >= start:
            if pred.start < start:
                start = pred.start
            if pred.end > end:
                end = pred.end
            root = _erase(root, pred.start)

        while True:
            succ = self._find_ge(root, start)
            if succ is not None and succ.start <= end:
                if succ.end > end:
                    end = succ.end
                root = _erase(root, succ.start)
            else:
                break

        self.root = _insert_node(root, _Node(start, end, self._next_priority()))

    def remove_interval(self, start, end):
        if end <= start:
            return

        root = self.root
        pred = self._find_le(root, start)
        if pred is None:
            return

        a = pred.start
        b = pred.end
        root = _erase(root, a)

        if start > a:
            root = _insert_node(root, _Node(a, start, self._next_priority()))
        if end < b:
            root = _insert_node(root, _Node(end, b, self._next_priority()))

        self.root = root

    def intervals(self):
        result = []
        stack = []
        node = self.root

        while stack or node is not None:
            while node is not None:
                stack.append(node)
                node = node.left

            node = stack.pop()
            result.append([node.start, node.end])
            node = node.right

        return result


def allocate_intervals(limit: int, operations: list[dict]) -> dict:
    free = _FreeSet(limit)
    active = {}
    results = []

    for operation in operations:
        op = operation["op"]

        if op == "alloc":
            ident = operation["id"]
            size = operation["size"]
            align = operation["align"]

            if ident in active:
                results.append(None)
                continue

            start = free.query(size, align)
            if start is None:
                results.append(None)
                continue

            free.remove_interval(start, start + size)
            active[ident] = (start, size)
            results.append(start)

        elif op == "resize":
            ident = operation["id"]
            size = operation["size"]
            align = operation["align"]

            if ident not in active:
                results.append(None)
                continue

            old_start, old_size = active[ident]
            free.add_interval(old_start, old_start + old_size)

            kept = False
            if old_start % align == 0:
                gap = free.containing(old_start)
                if gap is not None and gap.end >= old_start + size:
                    free.remove_interval(old_start, old_start + size)
                    active[ident] = (old_start, size)
                    results.append(old_start)
                    kept = True

            if kept:
                continue

            new_start = free.query(size, align)

            if new_start is None:
                free.remove_interval(old_start, old_start + old_size)
                results.append(None)
            else:
                free.remove_interval(new_start, new_start + size)
                active[ident] = (new_start, size)
                results.append(new_start)

        elif op == "free":
            ident = operation["id"]

            if ident in active:
                start, size = active.pop(ident)
                free.add_interval(start, start + size)
                results.append(True)
            else:
                results.append(False)

        else:
            results.append(None)

    allocations = {
        ident: [start, size]
        for ident, (start, size) in active.items()
    }

    return {
        "results": results,
        "allocations": allocations,
        "free": free.intervals()
    }

