import codecs
import re

_LINE_BREAK_RE = re.compile(r'[\r\n]')
_RETRY_BASE = 10 ** 1000


class SSEParser:
    def __init__(self):
        self._decoder = codecs.getincrementaldecoder('utf-8')(errors='replace')
        self._at_start = True
        self._line_parts = []
        self._skip_lf = False
        self._data = []
        self._event = ""
        self._id = ""
        self._retry = None
        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")
        text = self._decoder.decode(chunk, final=False)
        return self._process_text(text)

    def finish(self) -> list[dict]:
        if self._finished:
            return []
        self._finished = True

        out = []
        text = self._decoder.decode(b'', final=True)
        out.extend(self._process_text(text))

        if self._line_parts:
            line = ''.join(self._line_parts)
            self._line_parts.clear()
            ev = self._process_line(line)
            if ev is not None:
                out.append(ev)

        return out

    def _process_text(self, text: str) -> list[dict]:
        if not text:
            return []

        if self._at_start:
            if text[0] == '\ufeff':
                text = text[1:]
            self._at_start = False
            if not text:
                return []

        out = []
        n = len(text)
        pos = 0

        if self._skip_lf:
            if text[0] == '\n':
                pos = 1
            self._skip_lf = False
            if pos >= n:
                return out

        for m in _LINE_BREAK_RE.finditer(text, pos):
            idx = m.start()
            if idx < pos:
                continue

            if idx > pos:
                self._line_parts.append(text[pos:idx])

            line = ''.join(self._line_parts)
            self._line_parts.clear()

            ev = self._process_line(line)
            if ev is not None:
                out.append(ev)

            ch = text[idx]
            if ch == '\r':
                if idx + 1 < n and text[idx + 1] == '\n':
                    pos = idx + 2
                else:
                    pos = idx + 1
                    if idx + 1 == n:
                        self._skip_lf = True
            else:
                pos = idx + 1

        if pos < n:
            self._line_parts.append(text[pos:])

        return out

    def _process_line(self, line: str):
        if line == '':
            if self._data:
                event = self._event if self._event != '' else 'message'
                data = '\n'.join(self._data)
                ev = {
                    "event": event,
                    "data": data,
                    "id": self._id,
                    "retry": self._retry,
                }
                self._data = []
                self._event = ""
                return ev

            self._data = []
            self._event = ""
            return None

        if line.startswith(':'):
            return None

        if ':' in line:
            field, value = line.split(':', 1)
        else:
            field = line
            value = ''

        if value.startswith(' '):
            value = value[1:]

        if field == 'data':
            self._data.append(value)
        elif field == 'event':
            self._event = value
        elif field == 'id':
            if '\x00' not in value:
                self._id = value
        elif field == 'retry':
            if value and all('0' <= c <= '9' for c in value):
                self._retry = self._parse_retry(value)

        return None

    @staticmethod
    def _parse_retry(s: str) -> int:
        if len(s) <= 4000:
            return int(s)

        first = len(s) % 1000
        if first:
            result = int(s[:first])
            start = first
        else:
            result = 0
            start = 0

        for i in range(start, len(s), 1000):
            result = result * _RETRY_BASE + int(s[i:i + 1000])

        return result
