import heapq

def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    reverse = {}
    for edge in edges:
        source, destination, weight = edge
        reverse.setdefault(destination, []).append((source, weight))

    dist = {goal: (0, 0)}
    heap = [(0, 0, goal)]

    while heap:
        cost, hops, node = heapq.heappop(heap)
        if dist.get(node) != (cost, hops):
            continue

        for previous, weight in reverse.get(node, ()):
            new_cost = cost + weight
            new_hops = hops + 1
            old = dist.get(previous)
            if old is None or (new_cost, new_hops) < old:
                dist[previous] = (new_cost, new_hops)
                heapq.heappush(heap, (new_cost, new_hops, previous))

    if start not in dist:
        return None

    total_cost, total_hops = dist[start]

    forward = {}
    for edge in edges:
        source, destination, weight = edge
        forward.setdefault(source, []).append((destination, weight))

    for outgoing in forward.values():
        outgoing.sort()

    path = [start]
    node = start
    remaining_cost = total_cost
    remaining_hops = total_hops

    while node != goal:
        next_node = None
        next_weight = None

        for candidate, weight in forward.get(node, ()):
            d = dist.get(candidate)
            if d is None:
                continue
            candidate_cost, candidate_hops = d
            if (weight + candidate_cost == remaining_cost and
                    1 + candidate_hops == remaining_hops):
                next_node = candidate
                next_weight = weight
                break

        if next_node is None:
            return None

        path.append(next_node)
        remaining_cost -= next_weight
        remaining_hops -= 1
        node = next_node

    return {"cost": total_cost, "path": path}

