            nc = cost + w
            nh = hops + 1
            old = dist.get(prev)
            if old is None or (nc, nh) < old:
                dist[prev] = (nc, nh)
                heapq.heappush(heap, (nc, nh, counter, prev))
                counter += 1

    if start not in dist:
        return None

    opt_cost, opt_hops = dist[start]
    path = [start]
    current = start
    rem_cost = opt_cost
    rem_hops = opt_hops

    while current != goal:
        best_node = None
        best_w = None

