class _SegMatcher:
    __slots__ = (
        'key', 'm', 'star_mask', 'question_mask', 'lit_masks',
        'literal', 'tokens', 'is_literal', 'has_star', 'has_question',
        'any_segment'
    )

    def __init__(self, key, m, star_mask, question_mask, lit_masks,
                 literal, tokens, is_literal, has_star, has_question,
                 any_segment):
        self.key = key
        self.m = m
        self.star_mask = star_mask
        self.question_mask = question_mask
        self.lit_masks = lit_masks
        self.literal = literal
        self.tokens = tokens
        self.is_literal = is_literal
        self.has_star = has_star
        self.has_question = has_question
        self.any_segment = any_segment


def _build_matcher(tokens):
    collapsed = []
    prev_star = False

    for kind, val in tokens:
        if kind == 'star':
            if not prev_star:
                collapsed.append(('star', None))
                prev_star = True
        else:
            collapsed.append((kind, val))
            prev_star = False

    key = tuple(collapsed)
    m = len(collapsed)

    star_mask = 0
    question_mask = 0
    lit_masks = {}
    literal_parts = []
    has_star = False
    has_question = False

    for i, (kind, val) in enumerate(collapsed):
        bit = 1 << i
        if kind == 'star':
            star_mask |= bit
            has_star = True
        elif kind == 'question':
            question_mask |= bit
            has_question = True
        else:
            lit_masks[val] = lit_masks.get(val, 0) | bit
            literal_parts.append(val)

    is_literal = (not has_star) and (not has_question)
    literal = ''.join(literal_parts) if is_literal else None
    any_segment = (m == 1 and star_mask == 1)

    return _SegMatcher(
        key, m, star_mask, question_mask, lit_masks,
        literal, tuple(collapsed), is_literal, has_star, has_question,
        any_segment
    )


def _match_segment(matcher, text):
    if matcher.is_literal:
        return text == matcher.literal

    if not matcher.has_star:
        if len(text) != matcher.m:
            return False
        for (kind, val), ch in zip(matcher.tokens, text):
            if kind == 'lit' and val != ch:
                return False
        return True

    if matcher.any_segment:
        return True

    star_mask = matcher.star_mask
    question_mask = matcher.question_mask
    lit_masks = matcher.lit_masks
    end_bit = 1 << matcher.m

    active = 1
    active |= (active & star_mask) << 1

    for ch in text:
        match_mask = question_mask | lit_masks.get(ch, 0)
        nxt = (active & star_mask) | ((active & match_mask) << 1)
        if nxt == 0:
            return False
        active = nxt | ((nxt & star_mask) << 1)

    return (active & end_bit) != 0


def _parse_pattern(pattern):
    if pattern == "":
        return []

    if pattern[0] == '/' or pattern[-1] == '/' or '//' in pattern:
        raise ValueError("invalid pattern")

    raw_segments = pattern.split('/')
    compiled = []

    for seg in raw_segments:
        if seg == "":
            raise ValueError("invalid pattern")

        tokens = []
        i = 0
        length = len(seg)

        while i < length:
            ch = seg[i]
            if ch == '\\':
                if i + 1 >= length:
                    raise ValueError("trailing backslash in pattern segment")
                tokens.append(('lit', seg[i + 1]))
                i += 2
            elif ch == '*':
                tokens.append(('star', None))
                i += 1
            elif ch == '?':
                tokens.append(('question', None))
                i += 1
            else:
                tokens.append(('lit', ch))
                i += 1

        if len(tokens) == 2 and tokens[0][0] == 'star' and tokens[1][0] == 'star':
            if not (compiled and compiled[-1] is None):
                compiled.append(None)
        else:
            compiled.append(_build_matcher(tokens))

    return compiled


def path_glob(pattern: str, path: str) -> bool:
    compiled = _parse_pattern(pattern)

    if path == "":
        path_segments = []
    else:
        path_segments = path.split('/')

    n = len(path_segments)
    all_mask = (1 << (n + 1)) - 1
    all_path_mask = (1 << n) - 1

    dp = 1

    needed_literals = set()
    for seg in compiled:
        if seg is not None and seg.is_literal:
            needed_literals.add(seg.literal)

    positions_indices = {}
    if needed_literals:
        positions_indices = {lit: [] for lit in needed_literals}
        for idx, s in enumerate(path_segments):
            if s in needed_literals:
                positions_indices[s].append(idx)

    literal_mask_cache = {}
    mask_cache = {}
    CACHE_LIMIT = 256

    def get_literal_mask(lit):
        if lit in literal_mask_cache:
            return literal_mask_cache[lit]

        indices = positions_indices.get(lit, ())

        if not indices:
            mask = 0
        elif len(indices) * 16 < n:
            mask = 0
            for j in indices:
                mask |= 1 << j
        else:
            arr = bytearray((n + 7) // 8)
            for j in indices:
                arr[j >> 3] |= 1 << (j & 7)
            mask = int.from_bytes(arr, 'little')

        if len(literal_mask_cache) < CACHE_LIMIT:
            literal_mask_cache[lit] = mask

        return mask

    def compute_mask(matcher):
        if n == 0:
            return 0

        arr = bytearray((n + 7) // 8)
        match = _match_segment

        for j, s in enumerate(path_segments):
            if match(matcher, s):
                arr[j >> 3] |= 1 << (j & 7)

        return int.from_bytes(arr, 'little')

    for seg in compiled:
        if seg is None:
            if dp == 0:
                return False
            low = (dp & -dp).bit_length() - 1
            dp = all_mask ^ ((1 << low) - 1)
            continue

        if dp == 0:
            return False

        count = dp.bit_count()

        if count == 1:
            j = dp.bit_length() - 1
            if j < n and _match_segment(seg, path_segments[j]):
                dp = 1 << (j + 1)
            else:
                return False
            continue

        if seg.any_segment:
            dp = ((dp & all_path_mask) << 1)
        elif seg.is_literal:
            mask = get_literal_mask(seg.literal)
            dp = (dp & mask) << 1
        else:
            key = seg.key

            if key in mask_cache:
