class _SegMatcher:
    __slots__ = (
        'key', 'm', 'star_mask', 'question_mask', 'lit_masks',
        'literal', 'tokens', 'is_literal', 'has_star', 'has_question',
        'any_segment'
    )

    def __init__(self, key, m, star_mask, question_mask, lit_masks,
                 literal, tokens, is_literal, has_star, has_question,
                 any_segment):
        self.key = key
        self.m = m
        self.star_mask = star_mask
        self.question_mask = question_mask
        self.lit_masks = lit_masks
        self.literal = literal
        self.tokens = tokens
        self.is_literal = is_literal
        self.has_star = has_star
        self.has_question = has_question
        self.any_segment = any_segment


def _build_matcher(tokens):
    collapsed = []
    prev_star = False

    for kind, val in tokens:
        if kind == 'star':
            if not prev_star:
                collapsed.append(('star', None))
                prev_star = True
        else:
            collapsed.append((kind, val))
            prev_star = False

    key = tuple(collapsed)
    m = len(collapsed)

    star_mask = 0
    question_mask = 0
    lit_masks = {}
    literal_parts = []
    has_star = False
    has_question = False

    for i, (kind, val) in enumerate(collapsed):
        bit = 1 << i
        if kind == 'star':
            star_mask |= bit
            has_star = True
        elif kind == 'question':
            question_mask |= bit
            has_question = True
        else:
            lit_masks[val] = lit_masks.get(val, 0) | bit
            literal_parts.append(val)

    is_literal = (not has_star) and (not has_question)
    literal = ''.join(literal_parts) if is_literal else None
    any_segment = (m == 1 and star_mask == 1)

    return _SegMatcher(
        key, m, star_mask, question_mask, lit_masks,
        literal, tuple(collapsed), is_literal, has_star, has_question,
        any_segment
    )


def _match_segment(matcher, text):
    if matcher.is_literal:
        return text == matcher.literal

    if not matcher.has_star:
        if len(text) != matcher.m:
            return False
        for (kind, val), ch in zip(matcher.tokens, text):
            if kind == 'lit' and val != ch:
                return False
        return True

    if matcher.any_segment:
        return True

    star_mask = matcher.star_mask
    question_mask = matcher.question_mask
    lit_masks = matcher.lit_masks
    end_bit = 1 << matcher.m

    active = 1
    active |= (active & star_mask) << 1

    for ch in text:
        match_mask = question_mask | lit_masks.get(ch, 0)
        nxt = (active & star_mask) | ((active & match_mask) << 1)
        if nxt == 0:
            return False
        active = nxt | ((nxt & star_mask) << 1)

    return (active & end_bit) != 0


def _parse_pattern(pattern):
    if pattern == "":
        return []

    if pattern[0] == '/' or pattern[-1] == '/' or '//' in pattern:
        raise ValueError("invalid pattern")

    raw_segments = pattern.split('/')
    compiled = []

    for seg in raw_segments:
        if seg == "":
            raise ValueError("invalid pattern")

        tokens = []
        i = 0
        length = len(seg)

        while i < length:
            ch = seg[i]
            if ch == '\\':
                if i + 1 >= length:
                    raise ValueError("trailing backslash in pattern segment")
                tokens.append(('lit', seg[i + 1]))
                i += 2
            elif ch == '*':
                tokens.append(('star', None))
                i += 1
            elif ch == '?':
                tokens.append(('question', None))
                i += 1
            else:
                tokens.append(('lit', ch))
                i += 1

        if (len(tokens) == 2 and tokens[0][0] == 'star'
                and tokens[1][0] == 'star'):
            if not (compiled and compiled[-1] is None):
                compiled.append(None)
        else:
            compiled.append(_build_matcher(tokens))

    return compiled


