def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    deps_by_id = {}
    reversible_by_id = {}
    ids = []

    for entry in migrations:
        try:
            mid = entry["id"]
            raw_deps = entry["deps"]
            reversible = entry["reversible"]
        except (KeyError, TypeError):
            raise ValueError("invalid registry entry")

        if not isinstance(mid, str):
            raise ValueError("invalid migration id")
        if mid in deps_by_id:
            raise ValueError("duplicate migration id")

        seen = set()
        deps = []
        for dep in raw_deps:
            if dep not in seen:
                seen.add(dep)
                deps.append(dep)

        deps_by_id[mid] = deps
        reversible_by_id[mid] = reversible
        ids.append(mid)

    for mid in ids:
        for dep in deps_by_id[mid]:
            if dep not in deps_by_id:
                raise ValueError("unknown dependency")
            if dep == mid:
                raise ValueError("self dependency")

    indegree = {}
    dependents = {}
    for mid in ids:
        indegree[mid] = len(deps_by_id[mid])
        dependents[mid] = []

    for mid in ids:
        for dep in deps_by_id[mid]:
            dependents[dep].append(mid)

    queue = [mid for mid in ids if indegree[mid] == 0]
    head = 0
    processed = 0
    while head < len(queue):
        current = queue[head]
        head += 1
        processed += 1
        for dependent in dependents[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                queue.append(dependent)

    if processed != len(ids):
        raise ValueError("dependency cycle")

    applied_set = set(applied)
    target_set = set(target)

    for mid in applied_set:
        if mid not in deps_by_id:
            raise ValueError("unknown applied migration")
    for mid in target_set:
        if mid not in deps_by_id:
            raise ValueError("unknown target migration")

    for mid in applied_set:
        for dep in deps_by_id[mid]:
            if dep not in applied_set:
                raise ValueError("applied migrations are not dependency-closed")

    desired = set(target_set)
    stack = list(target_set)
    while stack:
        current = stack.pop()
        for dep in deps_by_id[current]:
            if dep not in desired:
                desired.add(dep)
                stack.append(dep)

    rollback = applied_set - desired
    for mid in rollback:
        if not reversible_by_id[mid]:
            raise ValueError("irreversible removal required")

    plan = []

    if rollback:
        dependent_count = {mid: 0 for mid in rollback}

        for mid in applied_set:
            for dep in deps_by_id[mid]:
