            item = heapq.heappop(heap)
            mid = item.value

            if mid not in remaining:
                continue

            remaining.remove(mid)
            plan.append("-" + mid)

            for dep in deps_by_id[mid]:
                if dep in dependent_count and dep in remaining:
                    dependent_count[dep] -= 1
                    if dependent_count[dep] == 0:
                        heapq.heappush(heap, _MaxStr(dep))

    applied_current = applied_set & desired
    missing = desired - applied_current

    if missing:
        missing_dependency_count = {mid: 0 for mid in missing}
        missing_dependents = {mid: [] for mid in missing}

        for mid in missing:
            count = 0
            for dep in deps_by_id[mid]:
                if dep not in applied_current:
                    count += 1
                if dep in missing:
                    missing_dependents[dep].append(mid)
            missing_dependency_count[mid] = count

        forward_heap = []
        for mid, count in missing_dependency_count.items():
            if count == 0:
                heapq.heappush(forward_heap, mid)

        applied_count = 0
        while forward_heap:
            mid = heapq.heappop(forward_heap)
            plan.append("+" + mid)
            applied_current.add(mid)
            applied_count += 1

            for dependent in missing_dependents[mid]:
                missing_dependency_count[dependent] -= 1
                if missing_dependency_count[dependent] == 0:
                    heapq.heappush(forward_heap, dependent)

        if applied_count != len(missing):
            raise ValueError("cannot complete forward migration")

    return plan

