class _FreeTree:
    __slots__ = ("root", "_seed")

    def __init__(self):
        self.root = None
        self._seed = 0x9E3779B97F4A7C15

    def _next_prio(self):
        x = self._seed
        x ^= (x << 7) & 0xFFFFFFFFFFFFFFFF
        x ^= x >> 9
        x ^= (x << 8) & 0xFFFFFFFFFFFFFFFF
        x &= 0xFFFFFFFFFFFFFFFF
        self._seed = x
        return x

    def _update(self, node):
        if node is not None:
            m = node.end - node.start
            left = node.left
            if left is not None and left.max_len > m:
                m = left.max_len
            right = node.right
            if right is not None and right.max_len > m:
                m = right.max_len
            node.max_len = m

    def _rotate_right(self, y):
        x = y.left
        y.left = x.right
        x.right = y
        self._update(y)
        self._update(x)
        return x

    def _rotate_left(self, x):
        y = x.right
        x.right = y.left
        y.left = x
        self._update(x)
        self._update(y)
        return y

    def _insert(self, root, node):
        if root is None:
            return node
        if node.start < root.start:
            root.left = self._insert(root.left, node)
            if root.left.prio < root.prio:
                root = self._rotate_right(root)
        elif node.start > root.start:
            root.right = self._insert(root.right, node)
            if root.right.prio < root.prio:
                root = self._rotate_left(root)
        else:
            if node.end > root.end:
                root.end = node.end
        self._update(root)
        return root

    def insert(self, start, end):
        node = _Node(start, end, self._next_prio())
        self.root = self._insert(self.root, node)

    def _delete(self, root, key):
        if root is None:
            return None
        if key < root.start:
            root.left = self._delete(root.left, key)
        elif key > root.start:
            root.right = self._delete(root.right, key)
        else:
            if root.left is None:
                return root.right
            if root.right is None:
                return root.left
            if root.left.prio < root.right.prio:
                root = self._rotate_right(root)
                root.right = self._delete(root.right, key)
            else:
                root = self._rotate_left(root)
                root.left = self._delete(root.left, key)
        self._update(root)
        return root

    def delete(self, start):
        self.root = self._delete(self.root, start)

    def find_containing(self, pos):
        cur = self.root
        while cur is not None:
            if pos < cur.start:
                cur = cur.left
            elif pos >= cur.end:
                cur = cur.right
            else:
                return cur
        return None

    def predecessor(self, key):
        cur = self.root
        res = None
        while cur is not None:
            if cur.start < key:
                res = cur
                cur = cur.right
            else:
                cur = cur.left
        return res

    def lower_bound(self, key):
        cur = self.root
        res = None
        while cur is not None:
            if cur.start >= key:
                res = cur
                cur = cur.left
            else:
                cur = cur.right
