        kind = op.get("op")

        if kind == "alloc":
            oid = op["id"]
            if oid in active:
                results.append(None)
                continue

            size = op["size"]
            align = op["align"]
            start = tree.find_start(size, align)
            if start is None:
                results.append(None)
            else:
                tree.take_exact(start, size)
                active[oid] = (start, size)
                results.append(start)

        elif kind == "resize":
            oid = op["id"]
            if oid not in active:
                results.append(None)
