import heapq

def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    forward = {}
    reverse = {}

    for edge in edges:
        source = edge[0]
        destination = edge[1]
        weight = edge[2]

        if source in forward:
            forward[source].append((destination, weight))
        else:
            forward[source] = [(destination, weight)]

        if destination in reverse:
            reverse[destination].append((source, weight))
        else:
            reverse[destination] = [(source, weight)]

    best = {goal: (0, 0)}
    heap = [(0, 0, goal)]

    while heap:
        cost, hops, node = heapq.heappop(heap)
        if best.get(node) != (cost, hops):
            continue

        for previous, weight in reverse.get(node, ()):
            new_cost = cost + weight
            new_hops = hops + 1
            old = best.get(previous)

            if old is None or new_cost < old[0] or (
                new_cost == old[0] and new_hops < old[1]
            ):
                best[previous] = (new_cost, new_hops)
                heapq.heappush(heap, (new_cost, new_hops, previous))

    if start not in best:
        return None

    total_cost, total_hops = best[start]
    path = [start]
    node = start
    remaining_cost = total_cost
    remaining_hops = total_hops

    while node != goal:
        next_node = None

        for candidate, weight in forward.get(node, ()):
            candidate_best = best.get(candidate)
            if candidate_best is None:
                continue

            if (
                weight + candidate_best[0] == remaining_cost
                and 1 + candidate_best[1] == remaining_hops
            ):
                if next_node is None or candidate < next_node:
                    next_node = candidate

        if next_node is None:
            return None

        path.append(next_node)
        node = next_node
        remaining_cost, remaining_hops = best[node]

    return {"cost": total_cost, "path": path}

