import heapq


def run_cache(capacity: int, operations: list[dict]) -> list:
    entries = OrderedDict()
    expiry_heap = []
    cap = capacity
    results = []

    for operation in operations:
        t = operation["t"]

        while expiry_heap and expiry_heap[0][0] <= t:
            expiry, key = heapq.heappop(expiry_heap)
            item = entries.get(key)
            if item is not None and item[1] == expiry:
