from collections import OrderedDict
import heapq

def run_cache(capacity: int, operations: list[dict]) -> list:
    order = OrderedDict()
    entries = {}
    heap = []
    version = 0
    cap = capacity
    results = []

    def purge(t: int) -> None:
        while heap and heap[0][0] <= t:
            exp, key, ver = heapq.heappop(heap)
            ent = entries.get(key)
            if ent is not None and ent[2] == ver:
                del entries[key]
                del order[key]

    for op in operations:
        t = op["t"]
        purge(t)
        typ = op["op"]

        if typ == "put":
            key = op["key"]
            value = op["value"]
            ttl = op["ttl"]

            if ttl <= 0 or cap == 0:
                if key in entries:
                    del entries[key]
                    del order[key]
            else:
                expires_at = t + ttl
                version += 1

                if key in entries:
                    del order[key]

                entries[key] = [value, expires_at, version]
                order[key] = None
                heapq.heappush(heap, (expires_at, key, version))

                while len(entries) > cap:
                    old_key, _ = order.popitem(last=False)
                    del entries[old_key]

            results.append(None)

        elif typ == "get":
            key = op["key"]
            ent = entries.get(key)

            if ent is None:
                results.append(None)
            else:
                order.move_to_end(key)
                results.append(ent[0])

        elif typ == "delete":
            key = op["key"]

            if key in entries:
                del entries[key]
                del order[key]
                results.append(True)
            else:
                results.append(False)

        elif typ == "items":
            results.append([[k, entries[k][0]] for k in order])

        elif typ == "resize":
            cap = op["capacity"]

            while len(entries) > cap:
                old_key, _ = order.popitem(last=False)
                del entries[old_key]

            results.append(None)

        else:
            results.append(None)

        if len(heap) > 2 * len(entries) + 1024:
            heap = [(ent[1], key, ent[2]) for key, ent in entries.items()]
            heapq.heapify(heap)

    return results

def _div_round_half_up(num: int, den: int) -> int:
    q, r = divmod(num, den)
    if r * 2 >= den:
        q += 1
    return q


def _parse_fixed(s: str) -> tuple[int, int]:
    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""
    if whole == "":
        whole = "0"
    digits = whole + frac
    if digits == "":
        num = 0
    else:
        num = int(digits)
    return num, 10 ** len(frac)


def _fmt(cents: int) -> str:
    return f"{cents // 100}.{cents % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    rate_num, rate_scale = _parse_fixed(tax_rate)
    coupon_num, coupon_scale = _parse_fixed(coupon)
    coupon_cents = _div_round_half_up(coupon_num * 100, coupon_scale)

    grosses = []
    for item in items:
        unit_num, unit_scale = _parse_fixed(item["unit"])
        qty = item["qty"]
        gross_cents = _div_round_half_up(unit_num * qty * 100, unit_scale)
        grosses.append(gross_cents)

    subtotal = sum(grosses)

    discount_total = coupon_cents
    if discount_total > subtotal:
        discount_total = subtotal
    if discount_total < 0:
        discount_total = 0

    n = len(items)
    discounts = [0] * n

    if subtotal > 0 and discount_total > 0:
        remainders = [0] * n
        allocated = 0

        for i, gross in enumerate(grosses):
            numerator = discount_total * gross
            base, remainder = divmod(numerator, subtotal)
            discounts[i] = base
            remainders[i] = remainder
            allocated += base

        remaining = discount_total - allocated
        if remaining:
            order = sorted(range(n), key=lambda i: (-remainders[i], i))
            for i in order[:remaining]:
                discounts[i] += 1

    lines = []
    invoice_net = 0
    invoice_tax = 0

    for i, item in enumerate(items):
        gross = grosses[i]
        discount = discounts[i]
        net = gross - discount

        if item["taxable"]:
            tax = _div_round_half_up(net * rate_num, rate_scale)
        else:
            tax = 0

        total = net + tax
        invoice_net += net
        invoice_tax += tax

        lines.append({
            "gross": _fmt(gross),
            "discount": _fmt(discount),
            "net": _fmt(net),
            "tax": _fmt(tax),
            "total": _fmt(total),
        })

    invoice_total = invoice_net + invoice_tax

    return {
        "lines": lines,
        "subtotal": _fmt(subtotal),
        "discount": _fmt(discount_total),
        "net": _fmt(invoice_net),
        "tax": _fmt(invoice_tax),
        "total": _fmt(invoice_total),
    }

import heapq
from collections import defaultdict


def shortest_route(edges: list[list], start: str, goal: str) -> dict | None:
    if start == goal:
        return {"cost": 0, "path": [start]}

    reverse = defaultdict(list)
    for edge in edges:
        source, destination, weight = edge[0], edge[1], edge[2]
        reverse[destination].append((source, weight))

    dist = {goal: (0, 0)}
    heap = [(0, 0, goal)]

    while heap:
        cost, hops, node = heapq.heappop(heap)
        if dist.get(node) != (cost, hops):
            continue
        if node == start:
            break

        for previous, weight in reverse.get(node, ()):
            new_cost = cost + weight
            new_hops = hops + 1
            old = dist.get(previous)
            if old is None or (new_cost, new_hops) < old:
                dist[previous] = (new_cost, new_hops)
                heapq.heappush(heap, (new_cost, new_hops, previous))

    start_dist = dist.get(start)
    if start_dist is None:
        return None

    del reverse

    adjacency = defaultdict(list)
    for edge in edges:
        source, destination, weight = edge[0], edge[1], edge[2]
        adjacency[source].append((destination, weight))

    target_cost, target_hops = start_dist
    path = [start]
    current = start

    while current != goal:
        current_cost, current_hops = dist[current]
        next_node = None

        for neighbor, weight in adjacency.get(current, ()):
            neighbor_dist = dist.get(neighbor)
            if neighbor_dist is None:
                continue
            if (
                current_cost == weight + neighbor_dist[0]
                and current_hops == 1 + neighbor_dist[1]
            ):
                if next_node is None or neighbor < next_node:
                    next_node = neighbor

        if next_node is None:
            return None

        path.append(next_node)
        current = next_node

    return {"cost": target_cost, "path": path}

