def _parse_decimal(s: str) -> tuple[int, int]:
    s = s.strip()
    if s.startswith('+'):
        s = s[1:]
    if s.startswith('-'):
        raise ValueError("negative decimal not allowed")
    if '.' in s:
        int_part, frac_part = s.split('.', 1)
        if '.' in frac_part:
            raise ValueError("invalid decimal")
    else:
        int_part, frac_part = s, ''
    if int_part == '':
        int_part = '0'
    for c in int_part:
        if c < '0' or c > '9':
            raise ValueError("invalid decimal")
    for c in frac_part:
        if c < '0' or c > '9':
            raise ValueError("invalid decimal")
    if frac_part:
        den = 10 ** len(frac_part)
        num = int(int_part) * den + int(frac_part)
    else:
        den = 1
        num = int(int_part)
    return num, den


def _round_half_up_frac(n: int, d: int) -> int:
    return (2 * n + d) // (2 * d)


def _format_cents(c: int) -> str:
    return f"{c // 100}.{c % 100:02d}"


def invoice(items: list[dict], tax_rate: str, coupon: str) -> dict:
    n = len(items)
    grosses = [0] * n
    taxable = [False] * n

    for i, item in enumerate(items):
        unit_num, unit_den = _parse_decimal(item["unit"])
        qty = int(item["qty"])
        grosses[i] = _round_half_up_frac(unit_num * qty * 100, unit_den)
        taxable[i] = bool(item["taxable"])

    subtotal = sum(grosses)

    coupon_num, coupon_den = _parse_decimal(coupon)
    coupon_cents = _round_half_up_frac(coupon_num * 100, coupon_den)
    discount_total = coupon_cents if coupon_cents < subtotal else subtotal

    discounts = [0] * n
    if subtotal > 0 and discount_total > 0:
        base_sum = 0
        remainders = []
        for i, gross in enumerate(grosses):
            prod = discount_total * gross
            base = prod // subtotal
            rem = prod - base * subtotal
            discounts[i] = base
            base_sum += base
            if rem > 0:
