import codecs
import re

_LINE_RE = re.compile(r"\r\n|\r|\n")


def _decimal_to_int(s: str) -> int:
    try:
        return int(s)
    except ValueError:
        n = 0
        for i in range(0, len(s), 9):
            chunk = s[i:i + 9]
            n = n * (10 ** len(chunk)) + int(chunk)
        return n


class SSEParser:
    def __init__(self):
        self._decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        self._finished = False
        self._at_start = True
        self._skip_lf = False
        self._line = []
        self._data = []
        self._event = ""
        self._id = ""
        self._retry = None

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")

        events = []
        text = self._decoder.decode(chunk, final=False)
        if text:
            self._process_text(text, events)
        return events

    def finish(self) -> list[dict]:
        if self._finished:
            return []

        self._finished = True
        events = []
        text = self._decoder.decode(b"", final=True)
        if text:
            self._process_text(text, events)

        if self._line:
            self._process_line(events)

        return events

    def _process_text(self, text: str, events: list[dict]) -> None:
        if self._at_start:
            if text:
                if text[0] == "\ufeff":
                    text = text[1:]
                self._at_start = False

        if not text:
            return

        if self._skip_lf:
            if text[0] == "\n":
                text = text[1:]
                self._skip_lf = False
                if not text:
                    return
            else:
                self._skip_lf = False

        pos = 0
        for match in _LINE_RE.finditer(text):
            start, end = match.span()
            if start > pos:
                self._line.append(text[pos:start])
            self._process_line(events)
            pos = end

        if pos < len(text):
            self._line.append(text[pos:])

        if text.endswith("\r"):
            self._skip_lf = True

    def _process_line(self, events: list[dict]) -> None:
        line = "".join(self._line)
        self._line.clear()

        if line == "":
            if self._data:
                event_name = self._event if self._event != "" else "message"
                events.append({
                    "event": event_name,
                    "data": "\n".join(self._data),
                    "id": self._id,
                    "retry": self._retry,
                })
            self._data.clear()
            self._event = ""
            return

        if line.startswith(":"):
            return

        sep = line.find(":")
        if sep == -1:
            field = line
            value = ""
        else:
            field = line[:sep]
            value = line[sep + 1:]
            if value.startswith(" "):
