import codecs
import re


class SSEParser:
    def __init__(self):
        self._decoder = codecs.getincrementaldecoder('utf-8')('replace')
        self._at_start = True
        self._skip_lf = False
        self._line_parts = []
        self._data = []
        self._event = ""
        self._id = ""
        self._retry = None
        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")
        events = []
        if chunk:
            text = self._decoder.decode(chunk, final=False)
            self._process_text(text, events)
        return events

    def finish(self) -> list[dict]:
        if self._finished:
            return []
        self._finished = True
        events = []
        text = self._decoder.decode(b'', final=True)
        self._process_text(text, events)
        if self._line_parts:
            line = ''.join(self._line_parts)
            self._line_parts.clear()
            self._process_line(line, events)
        self._data = []
        self._event = ""
        return events

    def _process_text(self, text, events):
        if not text:
            return

        if self._at_start:
            if text.startswith('\ufeff'):
                text = text[1:]
            self._at_start = False
            if not text:
                return

        if self._skip_lf:
            if text.startswith('\n'):
                text = text[1:]
                self._skip_lf = False
                if not text:
                    return
            else:
                self._skip_lf = False

        pos = 0
        n = len(text)

        for match in re.finditer(r'[\r\n]', text):
            i = match.start()
            if i < pos:
                continue

            if i > pos:
                self._line_parts.append(text[pos:i])

            line = ''.join(self._line_parts)
            self._line_parts.clear()
            self._process_line(line, events)

            ch = text[i]
            if ch == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    pos = i + 2
                else:
                    pos = i + 1
                    if i + 1 == n:
                        self._skip_lf = True
            else:
                pos = i + 1

        if pos < n:
            self._line_parts.append(text[pos:])

    def _process_line(self, line, events):
        if line == "":
            if self._data:
                data = "\n".join(self._data)
                event = self._event if self._event != "" else "message"
                events.append({
                    "event": event,
                    "data": data,
                    "id": self._id,
                    "retry": self._retry,
                })
            self._data = []
            self._event = ""
            return

        if line.startswith(':'):
            return

        idx = line.find(':')
        if idx == -1:
            field = line
            value = ""
        else:
            field = line[:idx]
            value = line[idx + 1:]
            if value.startswith(' '):
                value = value[1:]

        if field == 'data':
            self._data.append(value)
        elif field == 'event':
            self._event = value
        elif field == 'id':
            if '\x00' not in value:
                self._id = value
        elif field == 'retry':
            if value and all('0' <= c <= '9' for c in value):
                self._retry = self._parse_retry(value)

    def _parse_retry(self, value):
        try:
            return int(value)
        except ValueError:
            n = 0
            chunk_size = 1000
            pow10 = 10 ** chunk_size
            for i in range(0, len(value), chunk_size):
                chunk = value[i:i + chunk_size]
                if len(chunk) == chunk_size:
                    n = n * pow10 + int(chunk)
                else:
                    n = n * (10 ** len(chunk)) + int(chunk)
            return n

