import re

def path_glob(pattern: str, path: str) -> bool:
    # Validate and parse the entire pattern first.
    if pattern == "":
        return path == ""

    if pattern.startswith('/') or pattern.endswith('/') or '//' in pattern:
        raise ValueError("invalid pattern")

    raw_segments = pattern.split('/')
    if any(seg == "" for seg in raw_segments):
        raise ValueError("invalid pattern")

    parsed_segments = []
    for seg in raw_segments:
        tokens = []
        i = 0
        n = len(seg)
        while i < n:
            c = seg[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("trailing backslash")
                tokens.append((0, seg[i + 1]))  # literal
                i += 2
            elif c == '*':
                tokens.append((2, None))  # star
                i += 1
            elif c == '?':
                tokens.append((1, None))  # question mark
                i += 1
            else:
                tokens.append((0, c))  # literal
                i += 1

        is_globstar = (
            len(tokens) == 2
            and tokens[0][0] == 2
            and tokens[1][0] == 2
        )
        parsed_segments.append((is_globstar, tokens))

    # Split the path into segments.
    if path == "":
        path_segments = []
    else:
        path_segments = path.split('/')

    # Match the sequence of pattern segments against the path segments.
    p = 0
    s = 0
    star_p = -1
    star_s = 0
    plen = len(parsed_segments)
    slen = len(path_segments)

    while s < slen:
        if p < plen and not parsed_segments[p][0]:
            if match_segment(parsed_segments[p][1], path_segments[s]):
                p += 1
                s += 1
                continue
        elif p < plen and parsed_segments[p][0]:
            star_p = p
            star_s = s
            p += 1
            continue

        if star_p != -1:
            p = star_p + 1
            star_s += 1
            s = star_s
        else:
            return False

    while p < plen and parsed_segments[p][0]:
        p += 1

    return p == plen


def match_segment(tokens, s):
    """Match a single path segment against a token list."""
    has_star = any(t[0] == 2 for t in tokens)
    if not has_star:
        if len(tokens) != len(s):
            return False
        for tok, ch in zip(tokens, s):
            if tok[0] == 1:  # '?'
                continue
            if tok[1] != ch:
                return False
        return True

    # Split into chunks of non-star tokens.
    chunks = []
    current = []
    for tok in tokens:
        if tok[0] == 2:
            if current:
                chunks.append(current)
                current = []
        else:
            current.append(tok)
    if current:
        chunks.append(current)

    if not chunks:
        return True

    starts_with_star = tokens[0][0] == 2
    ends_with_star = tokens[-1][0] == 2
    pos = 0
    n = len(s)

    for idx, chunk in enumerate(chunks):
        is_first = (idx == 0)
        is_last = (idx == len(chunks) - 1)

        if is_first and not starts_with_star:
            if not match_chunk_at(chunk, s, pos):
                return False
            pos += len(chunk)
        elif is_last and not ends_with_star:
            start = n - len(chunk)
            if start < pos:
                return False
            if not match_chunk_at(chunk, s, start):
                return False
            pos = n
        else:
            found = find_chunk(chunk, s, pos)
            if found == -1:
                return False
            pos = found + len(chunk)

    return True


def match_chunk_at(chunk, s, start):
    if start < 0 or start + len(chunk) > len(s):
        return False
    for i, tok in enumerate(chunk):
        if tok[0] == 1:  # '?'
            continue
        if tok[1] != s[start + i]:
            return False
    return True


def match_char(tok, ch):
    if tok[0] == 1:  # '?'
        return True
    return tok[1] == ch


def match_safe(prefix_tok, suffix_tok):
    # Safe border relation: a literal in the prefix must match an identical
    # literal in the suffix. A '?' in the prefix matches anything.
    if prefix_tok[0] == 1:  # '?'
        return True
    if suffix_tok[0] == 1:  # '?'
        return False
    return prefix_tok[1] == suffix_tok[1]


def find_chunk(chunk, s, start):
    m = len(chunk)
    if m == 0:
        return start

    # Build the safe KMP failure function.
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and not match_safe(chunk[j], chunk[i]):
            j = fail[j - 1]
        if match_safe(chunk[j], chunk[i]):
            j += 1
        fail[i] = j

    # Search for the earliest occurrence at or after start.
    j = 0
    for i in range(start, len(s)):
        while j > 0 and not match_char(chunk[j], s[i]):
            j = fail[j - 1]
        if match_char(chunk[j], s[i]):
            j += 1
        if j == m:
            return i - m + 1
    return -1
