        if fixed_idx >= len(fixed):
            return False
        if len(path_segments) == 0:
            return False
        if not match_segment(fixed[fixed_idx], path_segments[-1]):
            return False
        if path_idx > len(path_segments) - 1:
            return False

    return True


def match_segment(tokens, s):
    chunks = []
    current = []
    for tok in tokens:
        if tok[0] == 2:
            if current:
                chunks.append(current)
                current = []
        else:
            current.append(tok)
    if current:
        chunks.append(current)

    if not chunks:
        return True

    starts_with_star = tokens[0][0] == 2
    ends_with_star = tokens[-1][0] == 2
    pos = 0
    n = len(s)

    for idx, chunk in enumerate(chunks):
        is_first = (idx == 0)
        is_last = (idx == len(chunks) - 1)

        if is_first and not starts_with_star:
            if not match_chunk_at(chunk, s, pos):
                return False
            pos += len(chunk)
        elif is_last and not ends_with_star:
            start = n - len(chunk)
            if start < pos:
                return False
            if not match_chunk_at(chunk, s, start):
                return False
            pos = n
        else:
            found = find_chunk(chunk, s, pos)
            if found == -1:
                return False
            pos = found + len(chunk)

    return True


def match_chunk_at(chunk, s, start):
    if start < 0 or start + len(chunk) > len(s):
        return False
    for i, tok in enumerate(chunk):
        if tok[0] == 1:
            continue
        if tok[1] != s[start + i]:
            return False
    return True


def find_chunk(chunk, s, start):
    m = len(chunk)
    n = len(s)
    if m == 0:
        return start

    first_lit_idx = -1
    first_lit_char = None
    for i, tok in enumerate(chunk):
        if tok[0] == 0:
            first_lit_idx = i
            first_lit_char = tok[1]
            break

    if first_lit_idx == -1:
        if start + m <= n:
            return start
        return -1

    search_start = start + first_lit_idx
    while True:
        idx = s.find(first_lit_char, search_start)
        if idx == -1:
            return -1
        chunk_start = idx - first_lit_idx
        if chunk_start < start:
            search_start = idx + 1
            continue
        if chunk_start + m > n:
            return -1
        if match_chunk_at(chunk, s, chunk_start):
            return chunk_start
        search_start = idx + 1
