        for d in rec["deps"]:
            if d == jid:
                raise ValueError("self dependency")
            if d not in ids:
                raise ValueError("unknown dependency")

    dependents = {jid: [] for jid in records}
    indegree = {jid: len(rec["deps"]) for jid, rec in records.items()}

    for jid, rec in records.items():
        for d in rec["deps"]:
            dependents[d].append(jid)

    q = [jid for jid, deg in indegree.items() if deg == 0]
    idx = 0
    processed = 0

    while idx < len(q):
        jid = q[idx]
        idx += 1
        processed += 1
        for dep in dependents[jid]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                q.append(dep)

    if processed != len(records):
        raise ValueError("cycle detected")

    remaining = {jid: len(rec["deps"]) for jid, rec in records.items()}
    ready = []

    for jid, rec in records.items():
        if remaining[jid] == 0:
            heapq.heappush(ready, (-rec["priority"], jid))

    running = []
    freed = []
    next_new = 0
    actions = []
    assigned_count = 0
    n = len(records)
    t = 0

