        while running and running[0][0] == t:
            end, w, jid = heapq.heappop(running)
            for dep in dependents[jid]:
                remaining[dep] -= 1
                if remaining[dep] == 0:
                    heapq.heappush(ready, (-records[dep]["priority"], dep))
            heapq.heappush(freed, w)

        while ready and (freed or next_new < workers):
            if freed:
