class _Fragment:
    __slots__ = ("tokens", "length", "literal", "runs", "all_question")

    def __init__(self, tokens):
        self.tokens = tokens
        self.length = len(tokens)
        if any(tok is True for tok in tokens):
            self.literal = None
        else:
            self.literal = "".join(tokens)
        self.all_question = all(tok is True for tok in tokens)

        runs = []
        i = 0
        n = len(tokens)
        while i < n:
            if tokens[i] is True:
                i += 1
            else:
                start = i
                chars = []
                while i < n and tokens[i] is not True:
                    chars.append(tokens[i])
                    i += 1
                runs.append((start, "".join(chars)))
        self.runs = runs


class _Segment:
    __slots__ = (
        "tokens",
        "literal",
        "has_star",
        "starts_star",
        "ends_star",
        "pieces",
        "specificity",
    )

    def __init__(
        self,
        tokens,
        literal,
        has_star,
        starts_star,
        ends_star,
        pieces,
        specificity,
    ):
        self.tokens = tokens
        self.literal = literal
        self.has_star = has_star
        self.starts_star = starts_star
        self.ends_star = ends_star
        self.pieces = pieces
        self.specificity = specificity


def _parse_segment(seg):
    if seg == "**":
        return None

    tokens = []
    i = 0
    n = len(seg)
    while i < n:
        c = seg[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("invalid pattern")
            tokens.append(seg[i + 1])
            i += 2
        elif c == "*":
            tokens.append(None)
            i += 1
        elif c == "?":
            tokens.append(True)
            i += 1
        else:
            tokens.append(c)
            i += 1

    pieces = []
    cur = []
    for tok in tokens:
        if tok is None:
            if cur:
                pieces.append(_Fragment(cur))
                cur = []
        else:
            cur.append(tok)
    if cur:
        pieces.append(_Fragment(cur))

    has_star = any(tok is None for tok in tokens)
    starts_star = bool(tokens) and tokens[0] is None
    ends_star = bool(tokens) and tokens[-1] is None

    if not has_star and all(tok is not True for tok in tokens):
        literal = "".join(tokens)
    else:
        literal = None

    lit_count = 0
    wild_count = 0
    for tok in tokens:
        if tok is None or tok is True:
            wild_count += 1
        else:
            lit_count += 1

    return _Segment(
        tokens,
        literal,
        has_star,
        starts_star,
        ends_star,
        pieces,
        lit_count * 10 - wild_count,
    )


def _match_frag_at(frag, text, start):
    n = len(text)
    if start < 0 or start + frag.length > n:
        return False

    lit = frag.literal
    if lit is not None:
        return text.startswith(lit, start)

    idx = start
    for tok in frag.tokens:
        if tok is not True and tok != text[idx]:
            return False
        idx += 1
    return True


def _build_positions(text):
    positions = {}
    for i, ch in enumerate(text):
        positions.setdefault(ch, []).append(i)
    return positions


def _find_frag(frag, text, pos, positions):
    q = frag.length
    m = len(text)
    if pos < 0:
        pos = 0
    if pos + q > m:
        return -1

    lit = frag.literal
    if lit is not None:
        return text.find(lit, pos)

    if frag.all_question:
        return pos

    best_start = 0
    best_run = None
    best_count = None

    for start, run in frag.runs:
        ch = run[0]
        lst = positions.get(ch)
        if lst is None:
            return -1

        idx = bisect.bisect_left(lst, pos + start)
        if idx >= len(lst):
            return -1

        cnt = len(lst) - idx
        better = False
        if best_count is None:
            better = True
        elif cnt < best_count:
            better = True
        elif cnt == best_count:
            lb = len(best_run) if best_run is not None else -1
            if len(run) > lb:
                better = True
            elif len(run) == lb and start > best_start:
                better = True

        if better:
            best_count = cnt
            best_run = run
            best_start = start

    search_from = pos + best_start
    occ = text.find(best_run, search_from)
    while occ != -1:
        cand = occ - best_start
        if cand + q > m:
            break
        if _match_frag_at(frag, text, cand):
            return cand
        occ = text.find(best_run, occ + 1)

    return -1


def _match_segment(spec, text):
    lit = spec.literal
    if lit is not None:
        return lit == text

    if not spec.has_star:
        tokens = spec.tokens
        if len(tokens) != len(text):
            return False
        for tok, ch in zip(tokens, text):
            if tok is not True and tok != ch:
                return False
        return True

    pieces = spec.pieces
    if not pieces:
        return True

    pos = 0
    m = len(text)
    positions = None
    plen = len(pieces)

    for idx, frag in enumerate(pieces):
        flen = frag.length
        is_first = idx == 0
        is_last = idx == plen - 1
        has_before = spec.starts_star if is_first else True
        has_after = spec.ends_star if is_last else True

        if not has_before:
            if pos + flen > m:
                return False
            if not _match_frag_at(frag, text, pos):
                return False
            pos += flen

        elif not has_after:
            start = m - flen
            if start < pos:
                return False
            if not _match_frag_at(frag, text, start):
                return False
            pos = start + flen

        else:
            if frag.literal is not None:
                found = text.find(frag.literal, pos)
                if found == -1:
                    return False
                pos = found + flen
            elif frag.all_question:
                if pos + flen > m:
                    return False
                pos += flen
            else:
                if positions is None:
                    positions = _build_positions(text)
                found = _find_frag(frag, text, pos, positions)
                if found == -1:
                    return False
                pos = found + flen

    return True


def _find_piece(piece, path_segments, pos):
    length = len(piece)
    n = len(path_segments)

    if length == 0:
        return pos
    if pos + length > n:
        return -1

    if length == 1:
        spec = piece[0]
        lit = spec.literal
        if lit is not None:
            try:
                return path_segments.index(lit, pos)
            except ValueError:
                return -1

        i = pos
        while i < n:
            if _match_segment(spec, path_segments[i]):
                return i
            i += 1
        return -1

    best_idx = 0
    best_score = None

    for idx, spec in enumerate(piece):
        if spec.literal is not None:
            score = (2, len(spec.literal))
        else:
            score = (1, spec.specificity)

        if (
            best_score is None
            or score > best_score
            or (score == best_score and idx > best_idx)
        ):
            best_score = score
            best_idx = idx

    anchor = piece[best_idx]

    order = sorted(
        range(length),
        key=lambda k: (
            (2, len(piece[k].literal))
            if piece[k].literal is not None
            else (1, piece[k].specificity)
        ),
        reverse=True,
    )

    start_min = pos
    start_max = n - length
    j_min = start_min + best_idx
    j_max = start_max + best_idx

    if anchor.literal is not None:
        lit = anchor.literal
        j = j_min

        while j <= j_max:
            try:
                occ = path_segments.index(lit, j, j_max + 1)
            except ValueError:
                return -1

            cand = occ - best_idx
            base = cand
            ok = True

            for k in order:
                if k == best_idx:
                    continue
                if not _match_segment(piece[k], path_segments[base + k]):
                    ok = False
                    break

            if ok:
                return cand

            j = occ + 1

        return -1

    j = j_min
    while j <= j_max:
        if _match_segment(anchor, path_segments[j]):
            cand = j - best_idx
            base = cand
            ok = True

            for k in order:
                if k == best_idx:
                    continue
                if not _match_segment(piece[k], path_segments[base + k]):
                    ok = False
                    break

            if ok:
                return cand

        j += 1

    return -1


def _match_specs(specs, path_segments):
    if not specs:
        return len(path_segments) == 0

    has_double = False
    for spec in specs:
        if spec is None:
            has_double = True
            break

    if not has_double:
        if len(specs) != len(path_segments):
            return False
        for spec, seg in zip(specs, path_segments):
            if not _match_segment(spec, seg):
                return False
        return True

    starts_double = specs[0] is None
    ends_double = specs[-1] is None

    pieces = []
    cur = []
    for spec in specs:
        if spec is None:
            if cur:
                pieces.append(cur)
                cur = []
        else:
            cur.append(spec)
    if cur:
        pieces.append(cur)

    if not pieces:
        return True

    pos = 0
    n = len(path_segments)
    num_pieces = len(pieces)

    for idx, piece in enumerate(pieces):
        length = len(piece)
        is_first = idx == 0
        is_last = idx == num_pieces - 1
        has_before = starts_double if is_first else True
        has_after = ends_double if is_last else True

        if not has_before:
            if pos + length > n:
                return False
            for k, spec in enumerate(piece):
                if not _match_segment(spec, path_segments[pos + k]):
                    return False
            pos += length

        elif not has_after:
            start = n - length
            if start < pos:
                return False
            for k, spec in enumerate(piece):
                if not _match_segment(spec, path_segments[start + k]):
                    return False
            pos = start + length

        else:
            found = _find_piece(piece, path_segments, pos)
            if found == -1:
                return False
            pos = found + length

    return True


def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        specs = []
    else:
        raw_segments = pattern.split("/")
        specs = []

        for seg in raw_segments:
            if seg == "":
                raise ValueError("invalid pattern")
            if seg == "**":
                specs.append(None)
            else:
                specs.append(_parse_segment(seg))

    if path == "":
        path_segments = []
    else:
        path_segments = path.split("/")

    return _match_specs(specs, path_segments)

