def _decode_token(raw):
    out = []
    i = 0
    n = len(raw)
    while i < n:
        ch = raw[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError
            nxt = raw[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise ValueError
            i += 2
        else:
