import copy


def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")
    if pointer == "":
        return []
    if pointer[0] != "/":
        raise ValueError("pointer must start with /")
    tokens = []
    for raw in pointer.split("/")[1:]:
        out = []
        i = 0
        n = len(raw)
        while i < n:
            c = raw[i]
            if c == "~":
                if i + 1 >= n:
                    raise ValueError("dangling ~")
                d = raw[i + 1]
                if d == "0":
                    out.append("~")
                elif d == "1":
                    out.append("/")
                else:
                    raise ValueError("invalid ~ escape")
                i += 2
            else:
                out.append(c)
                i += 1
        tokens.append("".join(out))
    return tokens


def _array_index(token):
    if token == "0":
        return 0
    if not token:
        raise ValueError("empty index")
    if not ("1" <= token[0] <= "9"):
        raise ValueError("invalid index")
    for c in token[1:]:
        if not ("0" <= c <= "9"):
            raise ValueError("invalid index")
    return int(token)


def _get(root, tokens):
    cur = root
    for t in tokens:
        if isinstance(cur, dict):
            if t not in cur:
                raise ValueError("missing key")
            cur = cur[t]
        elif isinstance(cur, list):
            idx = _array_index(t)
            if idx >= len(cur):
                raise ValueError("index out of range")
            cur = cur[idx]
        else:
            raise ValueError("cannot traverse scalar")
    return cur


def _parent(root, tokens):
    cur = root
    for t in tokens[:-1]:
        if isinstance(cur, dict):
            if t not in cur:
                raise ValueError("missing key")
            cur = cur[t]
        elif isinstance(cur, list):
            idx = _array_index(t)
            if idx >= len(cur):
                raise ValueError("index out of range")
            cur = cur[idx]
        else:
            raise ValueError("cannot traverse scalar")
    return cur


def _add(root, tokens, value):
    if not tokens:
        return copy.deepcopy(value)
    parent = _parent(root, tokens)
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = copy.deepcopy(value)
    elif isinstance(parent, list):
        if last == "-":
            parent.append(copy.deepcopy(value))
        else:
            idx = _array_index(last)
            if idx > len(parent):
                raise ValueError("index out of range")
            parent.insert(idx, copy.deepcopy(value))
    else:
        raise ValueError("cannot add to scalar")
    return root


def _remove(root, tokens):
    if not tokens:
        raise ValueError("cannot remove root")
    parent = _parent(root, tokens)
    last = tokens[-1]
    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing key")
        del parent[last]
    elif isinstance(parent, list):
        idx = _array_index(last)
        if idx >= len(parent):
            raise ValueError("index out of range")
        del parent[idx]
    else:
        raise ValueError("cannot remove from scalar")
    return root


def _replace(root, tokens, value):
    if not tokens:
        return copy.deepcopy(value)
    parent = _parent(root, tokens)
    last = tokens[-1]
    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing key")
        parent[last] = copy.deepcopy(value)
    elif isinstance(parent, list):
        idx = _array_index(last)
        if idx >= len(parent):
            raise ValueError("index out of range")
        parent[idx] = copy.deepcopy(value)
    else:
        raise ValueError("cannot replace in scalar")
    return root


def _equal(a, b):
    stack = [(a, b)]
    while stack:
        x, y = stack.pop()
        if isinstance(x, bool) or isinstance(y, bool):
            if not (isinstance(x, bool) and isinstance(y, bool) and x == y):
                return False
            continue
        if x is None or y is None:
            if not (x is None and y is None):
                return False
            continue
        if isinstance(x, (int, float)) and isinstance(y, (int, float)):
            if x != y:
                return False
            continue
        if isinstance(x, str) or isinstance(y, str):
            if not (isinstance(x, str) and isinstance(y, str) and x == y):
                return False
            continue
        if isinstance(x, list) or isinstance(y, list):
            if not (isinstance(x, list) and isinstance(y, list)):
                return False
            if len(x) != len(y):
                return False
            for i in range(len(x)):
                stack.append((x[i], y[i]))
            continue
        if isinstance(x, dict) or isinstance(y, dict):
            if not (isinstance(x, dict) and isinstance(y, dict)):
                return False
            if len(x) != len(y):
                return False
            for k, v in x.items():
                if k not in y:
                    return False
                stack.append((v, y[k]))
            continue
        if type(x) is not type(y) or x != y:
            return False
    return True


def apply_patch(document, operations):
    if not isinstance(operations, list):
        raise ValueError("operations must be a list")
    working = copy.deepcopy(document)
    for op in operations:
        if not isinstance(op, dict):
            raise ValueError("operation must be a dict")
        if "op" not in op or "path" not in op:
            raise ValueError("missing op or path")
        name = op["op"]
        if not isinstance(name, str):
            raise ValueError("op must be a string")
        if name not in ("add", "remove", "replace", "move", "copy", "test"):
            raise ValueError("unknown op")
        tokens = _parse_pointer(op["path"])
        if name == "add":
            if "value" not in op:
                raise ValueError("missing value")
            working = _add(working, tokens, op["value"])
        elif name == "remove":
            working = _remove(working, tokens)
        elif name == "replace":
            if "value" not in op:
                raise ValueError("missing value")
            working = _replace(working, tokens, op["value"])
        elif name == "test":
            if "value" not in op:
                raise ValueError("missing value")
            target = _get(working, tokens)
            if not _equal(target, op["value"]):
                raise ValueError("test failed")
        elif name == "copy":
            if "from" not in op:
                raise ValueError("missing from")
            src_tokens = _parse_pointer(op["from"])
            src_val = _get(working, src_tokens)
            working = _add(working, tokens, src_val)
        elif name == "move":
            if "from" not in op:
                raise ValueError("missing from")
            src_tokens = _parse_pointer(op["from"])
            src_val = _get(working, src_tokens)
            if src_tokens == tokens:
                continue
            if len(tokens) > len(src_tokens) and tokens[:len(src_tokens)] == src_tokens:
                raise ValueError("cannot move into descendant")
            working = _remove(working, src_tokens)
            working = _add(working, tokens, src_val)
    return working
