def _is_int_not_bool(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _is_number(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)


def _eq(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if _is_number(a) and _is_number(b):
        return a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return _dict_eq(a, b)
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_eq(x, y) for x, y in zip(a, b))
    if isinstance(a, tuple) and isinstance(b, tuple):
        if len(a) != len(b):
            return False
        return all(_eq(x, y) for x, y in zip(a, b))
    return a == b


def _dict_eq(a, b):
    if len(a) != len(b):
        return False
    if all(isinstance(k, str) for k in a) and all(isinstance(k, str) for k in b):
        if set(a.keys()) != set(b.keys()):
            return False
        for k in a:
            if not _eq(a[k], b[k]):
                return False
        return True
    b_items = list(b.items())
    used = [False] * len(b_items)
    for ka, va in a.items():
        found = False
        for i, (kb, vb) in enumerate(b_items):
            if not used[i] and _eq(ka, kb) and _eq(va, vb):
                used[i] = True
                found = True
                break
        if not found:
            return False
    return True


def replay_ledger(initial, events):
    balances = dict(initial)
    seen = {}
    results = []

    for event in events:
        eid = event["id"]

        if eid in seen:
            if _eq(event, seen[eid]):
                status = "duplicate"
            else:
                status = "conflict"
            results.append({"id": eid, "status": status})
            continue

        seen[eid] = event

        valid = True
        moves = event.get("moves", [])
        if not isinstance(moves, list):
            valid = False
            moves = []
        else:
            for move in moves:
                if not isinstance(move, (list, tuple)) or len(move) != 3:
                    valid = False
                    break
                src, dst, amt = move
                if not isinstance(src, str) or not isinstance(dst, str):
                    valid = False
                    break
                if src not in balances or dst not in balances or src == dst:
                    valid = False
                    break
                if not _is_int_not_bool(amt) or amt <= 0:
                    valid = False
