        expected = event.get("expected", {})
        if not isinstance(expected, dict):
            valid = False
            expected = {}
        else:
            for k, v in expected.items():
                if not isinstance(k, str) or k not in balances:
                    valid = False
                    break
                if not _is_int_not_bool(v):
                    valid = False
                    break

        if not valid:
            results.append({"id": eid, "status": "invalid"})
            continue

        guard_fail = False
        for k, v in expected.items():
            if balances[k] != v:
                guard_fail = True
                break

        if guard_fail:
            results.append({"id": eid, "status": "guard"})
            continue

        tentative = dict(balances)
        insufficient = False
        for move in moves:
            src, dst, amt = move
            if tentative[src] < amt:
                insufficient = True
                break
            tentative[src] -= amt
            tentative[dst] += amt

        if insufficient:
            results.append({"id": eid, "status": "insufficient"})
            continue

        balances = tentative
        results.append({"id": eid, "status": "applied"})

    return {"balances": balances, "results": results}

