        self.left = None
        self.right = None
        self.height = 1
        self.min_start = start
        self.max_end = end


def _h(t):
    return t.height if t is not None else 0


def _update(t):
    if t is None:
        return
    l = t.left
    r = t.right
    lh = l.height if l is not None else 0
    rh = r.height if r is not None else 0
    t.height = (lh if lh > rh else rh) + 1
    t.min_start = l.min_start if l is not None else t.start
    me = t.end
    if l is not None and l.max_end > me:
        me = l.max_end
    if r is not None and r.max_end > me:
        me = r.max_end
    t.max_end = me


def _rotate_left(x):
    y = x.right
    x.right = y.left
    y.left = x
    _update(x)
    _update(y)
    return y


def _rotate_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    _update(y)
    _update(x)
    return x


def _balance(t):
    _update(t)
    bf = _h(t.left) - _h(t.right)
    if bf > 1:
        if _h(t.left.left) < _h(t.left.right):
            t.left = _rotate_left(t.left)
        return _rotate_right(t)
    if bf < -1:
        if _h(t.right.right) < _h(t.right.left):
            t.right = _rotate_right(t.right)
        return _rotate_left(t)
    return t


def _insert(t, node):
    if t is None:
        return node
    if node.start < t.start:
        t.left = _insert(t.left, node)
    elif node.start > t.start:
        t.right = _insert(t.right, node)
    else:
        if node.end > t.end:
            t.end = node.end
        return _balance(t)
    return _balance(t)


def _min_node(t):
    while t.left is not None:
        t = t.left
    return t


def _delete(t, key):
    if t is None:
        return None
    if key < t.start:
        t.left = _delete(t.left, key)
    elif key > t.start:
        t.right = _delete(t.right, key)
    else:
        if t.left is None:
            return t.right
        if t.right is None:
            return t.left
        succ = _min_node(t.right)
        t.start = succ.start
        t.end = succ.end
        t.right = _delete(t.right, succ.start)
