            cur = cur.left
        cur = stack.pop()
        result.append([cur.start, cur.end])
        cur = cur.right
    return result


def allocate_intervals(limit, operations):
    root = _Node(0, limit) if limit > 0 else None
    allocations = {}
    results = []

    for op in operations:
        kind = op.get("op")

        if kind == "alloc":
            ident = op["id"]
            size = op["size"]
            align = op["align"]

            if ident in allocations:
                results.append(None)
