            if can_keep:
                allocations[ident] = [old_start, size]
                results.append(old_start)
                continue

            root = _insert_free(root, old_start, old_end)
            new_start = _find_fit(root, align, size)

            if new_start is None:
                root = _remove_free_range(root, old_start, old_end)
                results.append(None)
            else:
                root = _remove_free_range(root, new_start, new_start + size)
                allocations[ident] = [new_start, size]
                results.append(new_start)

        elif kind == "free":
            ident = op["id"]
            if ident in allocations:
                start, size = allocations.pop(ident)
                root = _insert_free(root, start, start + size)
                results.append(True)
            else:
                results.append(False)

        else:
            results.append(None)

    out_allocations = {}
    for ident, value in allocations.items():
        out_allocations[ident] = [value[0], value[1]]

    return {
        "results": results,
        "allocations": out_allocations,
        "free": _to_list(root),
    }

