        self.max_len = end - start


def _upd(node):
    m = node.end - node.start
    left = node.left
    right = node.right
    if left is not None and left.max_len > m:
        m = left.max_len
    if right is not None and right.max_len > m:
        m = right.max_len
    node.max_len = m


def _split(root, key):
    if root is None:
        return None, None
    if root.start < key:
        a, b = _split(root.right, key)
        root.right = a
        _upd(root)
        return root, b
    else:
        a, b = _split(root.left, key)
        root.left = b
        _upd(root)
        return a, root


def _merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.prio < b.prio:
        a.right = _merge(a.right, b)
        _upd(a)
        return a
    else:
        b.left = _merge(a, b.left)
        _upd(b)
        return b


def _insert(root, node):
    if root is None:
        return node
    if node.prio < root.prio:
        left, right = _split(root, node.start)
        node.left = left
        node.right = right
        _upd(node)
        return node
    if node.start < root.start:
        root.left = _insert(root.left, node)
    else:
        root.right = _insert(root.right, node)
    _upd(root)
    return root


def _erase(root, key):
    if root is None:
        return None
    if key < root.start:
        root.left = _erase(root.left, key)
    elif key > root.start:
        root.right = _erase(root.right, key)
    else:
        return _merge(root.left, root.right)
    _upd(root)
    return root


def _lower_bound(root, key):
    result = None
    while root is not None:
        if root.start >= key:
            result = root
            root = root.left
        else:
            root = root.right
    return result


def _predecessor(root, key):
    result = None
    while root is not None:
        if root.start < key:
            result = root
            root = root.right
        else:
            root = root.left
    return result


def _find_first_fit(root, size, align):
    if root is None or root.max_len < size:
        return None

    left = root.left
    if left is not None and left.max_len >= size:
        result = _find_first_fit(left, size, align)
        if result is not None:
            return result

    a = root.start
    b = root.end
    if b - a >= size:
        rem = a % align
        if rem == 0:
            x = a
        else:
            x = a + align - rem
        if x + size <= b:
            return root, x

    right = root.right
    if right is not None and right.max_len >= size:
        return _find_first_fit(right, size, align)
    return None


def _add_interval(root, s, e):
    removed = []

    pred = _predecessor(root, s)
    if pred is not None and pred.end >= s:
        removed.append((pred.start, pred.end))
        root = _erase(root, pred.start)
        if pred.start < s:
            s = pred.start
        if pred.end > e:
            e = pred.end

    while True:
        node = _lower_bound(root, s)
        if node is None or node.start > e:
            break
        removed.append((node.start, node.end))
        if node.end > e:
            e = node.end
        root = _erase(root, node.start)

    root = _insert(root, _Node(s, e))
    return root, removed, s, e


def allocate_intervals(limit, operations):
    allocations_map = {}
    root = None
    if limit > 0:
        root = _Node(0, limit)

    results = []

    for op in operations:
        kind = op["op"]

        if kind == "alloc":
            ident = op["id"]
            size = op["size"]
            align = op["align"]

            if ident in allocations_map:
                results.append(None)
                continue

            found = _find_first_fit(root, size, align)
            if found is None:
                results.append(None)
                continue

            node, x = found
            a = node.start
            b = node.end

            root = _erase(root, a)
            if a < x:
                root = _insert(root, _Node(a, x))
            end = x + size
            if end < b:
                root = _insert(root, _Node(end, b))

            allocations_map[ident] = [x, size]
            results.append(x)

        elif kind == "resize":
            ident = op["id"]
            if ident not in allocations_map:
                results.append(None)
                continue

            size = op["size"]
            align = op["align"]
            old = allocations_map[ident]
            start = old[0]
            old_size = old[1]

            if start % align == 0:
                if size <= old_size:
                    if size < old_size:
                        root, _, _, _ = _add_interval(
                            root, start + size, start + old_size
                        )
                    allocations_map[ident] = [start, size]
                    results.append(start)
                    continue
                else:
                    extension_start = start + old_size
                    extension_end = start + size
                    node = _lower_bound(root, extension_start)
                    if (
                        node is not None
                        and node.start == extension_start
                        and node.end >= extension_end
                    ):
                        old_free_end = node.end
                        root = _erase(root, extension_start)
                        if extension_end < old_free_end:
                            root = _insert(
                                root, _Node(extension_end, old_free_end)
                            )
                        allocations_map[ident] = [start, size]
                        results.append(start)
                        continue

            old_start = start
            old_end = start + old_size

            new_root, removed, merged_start, _ = _add_interval(
                root, old_start, old_end
            )
            found = _find_first_fit(new_root, size, align)

            if found is None:
                root = _erase(new_root, merged_start)
                for rs, re in removed:
                    root = _insert(root, _Node(rs, re))
                results.append(None)
            else:
                node, x = found
                a = node.start
                b = node.end

                new_root = _erase(new_root, a)
                if a < x:
                    new_root = _insert(new_root, _Node(a, x))
                end = x + size
                if end < b:
                    new_root = _insert(new_root, _Node(end, b))

                root = new_root
                allocations_map[ident] = [x, size]
                results.append(x)

        elif kind == "free":
            ident = op["id"]
            if ident not in allocations_map:
                results.append(False)
                continue

            old = allocations_map.pop(ident)
            start = old[0]
            end = start + old[1]
            root, _, _, _ = _add_interval(root, start, end)
            results.append(True)

    free_intervals = []
    stack = []
    node = root
    while node is not None or stack:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        free_intervals.append([node.start, node.end])
        node = node.right

    allocations = {}
    for ident, value in allocations_map.items():
        allocations[ident] = [value[0], value[1]]

    return {
        "results": results,
        "allocations": allocations,
        "free": free_intervals,
    }

