class _Node:
    __slots__ = ('start', 'end', 'prio', 'left', 'right', 'max_len')

    def __init__(self, start, end, prio):
        self.start = start
        self.end = end
        self.prio = prio
        self.left = None
        self.right = None
        self.max_len = end - start


class _FreeIntervals:
    def __init__(self, limit):
        self.root = None
        self.counter = 0
        if limit > 0:
            self.root = self._new_node(0, limit)

    def _next_prio(self):
        self.counter += 1
        x = self.counter
        x = (x + 0x9e3779b97f4a7c15) & 0xFFFFFFFFFFFFFFFF
        z = x
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9 & 0xFFFFFFFFFFFFFFFF
        z = (z ^ (z >> 27)) * 0x94d049bb133111eb & 0xFFFFFFFFFFFFFFFF
        z = z ^ (z >> 31)
        return z

    def _new_node(self, start, end):
        return _Node(start, end, self._next_prio())

    def _update(self, node):
        if node is None:
            return
        m = node.end - node.start
        if node.left is not None and node.left.max_len > m:
            m = node.left.max_len
        if node.right is not None and node.right.max_len > m:
            m = node.right.max_len
        node.max_len = m

    def _merge(self, a, b):
        if a is None:
            return b
        if b is None:
            return a
        if a.prio > b.prio:
            a.right = self._merge(a.right, b)
            self._update(a)
            return a
        else:
            b.left = self._merge(a, b.left)
            self._update(b)
            return b

    def _split(self, root, key):
        if root is None:
            return (None, None)
        if root.start < key:
            a, b = self._split(root.right, key)
            root.right = a
            self._update(root)
            return (root, b)
        else:
            a, b = self._split(root.left, key)
            root.left = b
            self._update(root)
            return (a, root)

    def _insert(self, root, node):
        if root is None:
            return node
        if node.prio > root.prio:
            left, right = self._split(root, node.start)
            node.left = left
            node.right = right
            self._update(node)
            return node
        elif node.start < root.start:
            root.left = self._insert(root.left, node)
        else:
            root.right = self._insert(root.right, node)
        self._update(root)
        return root

    def _delete(self, root, start):
        if root is None:
            return None
        if start < root.start:
            root.left = self._delete(root.left, start)
        elif start > root.start:
            root.right = self._delete(root.right, start)
        else:
            return self._merge(root.left, root.right)
        self._update(root)
        return root

    def _find_le(self, root, key):
        res = None
        while root is not None:
            if root.start <= key:
                res = root
                root = root.right
            else:
                root = root.left
        return res

    def _find_ge(self, root, key):
        res = None
        while root is not None:
            if root.start >= key:
                res = root
                root = root.left
            else:
                root = root.right
        return res

    def _find_interval_containing(self, root, pos):
        node = self._find_le(root, pos)
        if node is not None and pos < node.end:
            return node
        return None

    def find_fit(self, size, align):
        stack = []
        node = self.root
        while stack or node is not None:
            while node is not None:
                if node.max_len < size:
                    node = None
                    break
                stack.append(node)
                node = node.left
            if not stack:
                break
            node = stack.pop()
            a = node.start
            b = node.end
            if b - a >= size:
                x = ((a + align - 1) // align) * align
                if x + size <= b:
                    return x
            node = node.right
        return None

    def range_is_free(self, start, end):
        if start >= end:
            return True
        node = self._find_interval_containing(self.root, start)
        return node is not None and node.end >= end

    def add_range(self, start, end):
        if start >= end:
            return
        pred = self._find_le(self.root, start)
        if pred is not None and pred.end == start:
            new_start = pred.start
            self.root = self._delete(self.root, pred.start)
        else:
            new_start = start

        succ = self._find_ge(self.root, end)
        if succ is not None and succ.start == end:
            new_end = succ.end
            self.root = self._delete(self.root, succ.start)
        else:
            new_end = end

        node = self._new_node(new_start, new_end)
        self.root = self._insert(self.root, node)

    def remove_range(self, start, end):
        if start >= end:
            return
        node = self._find_interval_containing(self.root, start)
        if node is None:
            return
        a = node.start
        b = node.end
        self.root = self._delete(self.root, a)
        if a < start:
            self.root = self._insert(self.root, self._new_node(a, start))
        if end < b:
            self.root = self._insert(self.root, self._new_node(end, b))

    def to_list(self):
        res = []
        stack = []
        node = self.root
        while stack or node is not None:
            while node is not None:
                stack.append(node)
                node = node.left
            node = stack.pop()
            res.append([node.start, node.end])
            node = node.right
        return res


def allocate_intervals(limit: int, operations: list[dict]) -> dict:
    free = _FreeIntervals(limit)
    allocations = {}
    results = []

    for op in operations:
        kind = op["op"]

        if kind == "alloc":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ in allocations:
                results.append(None)
                continue

            start = free.find_fit(size, align)
            if start is None:
                results.append(None)
            else:
                allocations[id_] = (start, size)
                free.remove_range(start, start + size)
                results.append(start)

        elif kind == "resize":
            id_ = op["id"]
            size = op["size"]
            align = op["align"]

            if id_ not in allocations:
                results.append(None)
                continue

            old_start, old_size = allocations[id_]
            free.add_range(old_start, old_start + old_size)

            if old_start % align == 0 and free.range_is_free(old_start, old_start + size):
                new_start = old_start
            else:
                new_start = free.find_fit(size, align)

            if new_start is None:
                free.remove_range(old_start, old_start + old_size)
                results.append(None)
            else:
                free.remove_range(new_start, new_start + size)
                allocations[id_] = (new_start, size)
                results.append(new_start)

        elif kind == "free":
            id_ = op["id"]
            if id_ in allocations:
                start, size = allocations.pop(id_)
                free.add_range(start, start + size)
                results.append(True)
            else:
                results.append(False)

        else:
            results.append(None)

    final_allocations = {
        id_: [start, size]
        for id_, (start, size) in allocations.items()
    }

    return {
        "results": results,
        "allocations": final_allocations,
        "free": free.to_list(),
    }
