import codecs
import decimal


class SSEParser:
    def __init__(self) -> None:
        self._decoder = codecs.getincrementaldecoder("utf-8")("replace")
        self._at_start = True
        self._pending_cr = False
        self._line = []
        self._data = []
        self._event = ""
        self._id = ""
        self._retry = None
        self._finished = False

    def feed(self, chunk: bytes) -> list[dict]:
        if self._finished:
            raise ValueError("feed() called after finish()")
        text = self._decoder.decode(chunk, final=False)
        return self._process_text(text)

    def finish(self) -> list[dict]:
        if self._finished:
            return []
        self._finished = True
        text = self._decoder.decode(b"", final=True)
        events = self._process_text(text)
        if self._line:
            line = "".join(self._line)
            self._line = []
            self._process_line(line)
        return events

    def _process_text(self, text: str) -> list[dict]:
        events = []
        for ch in text:
            if self._at_start:
                if ch == "\ufeff":
                    self._at_start = False
                    continue
                self._at_start = False

            if self._pending_cr:
                self._pending_cr = False
                if ch == "\n":
                    continue

            if ch == "\r":
                self._end_line(events)
                self._pending_cr = True
            elif ch == "\n":
                self._end_line(events)
            else:
                self._line.append(ch)
        return events

    def _end_line(self, events: list[dict]) -> None:
        line = "".join(self._line)
        self._line = []
        self._process_line(line)
        if line == "":
            if self._data:
                event = self._event if self._event != "" else "message"
                data = "\n".join(self._data)
                events.append({
                    "event": event,
                    "data": data,
                    "id": self._id,
                    "retry": self._retry,
                })
            self._data = []
            self._event = ""

    def _process_line(self, line: str) -> None:
        if line.startswith(":"):
            return

        if ":" in line:
            field, value = line.split(":", 1)
        else:
            field, value = line, ""

        if value.startswith(" "):
            value = value[1:]

        if field == "data":
            self._data.append(value)
        elif field == "event":
            self._event = value
        elif field == "id":
            if "\x00" not in value:
                self._id = value
        elif field == "retry":
            if value and all("0" <= c <= "9" for c in value):
                self._retry = self._parse_retry(value)

    def _parse_retry(self, value: str) -> int:
        try:
            return int(value)
        except ValueError:
            return int(decimal.Decimal(value))

