import copy


def apply_patch(document, operations):
    result = copy.deepcopy(document)

    if not isinstance(operations, list):
        raise ValueError("operations must be a list")

    for operation in operations:
        if not isinstance(operation, dict):
            raise ValueError("operation must be an object")
        if "op" not in operation:
            raise ValueError("missing op")

        op = operation["op"]

        if op == "add":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _add(result, path, operation["value"])
        elif op == "remove":
            _require_keys(operation, ("path",))
            path = _parse_pointer(operation["path"])
            result = _remove(result, path)
        elif op == "replace":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _replace(result, path, operation["value"])
        elif op == "move":
            _require_keys(operation, ("path", "from"))
            source = _parse_pointer(operation["from"])
            destination = _parse_pointer(operation["path"])
            result = _move(result, source, destination)
        elif op == "copy":
            _require_keys(operation, ("path", "from"))
            source = _parse_pointer(operation["from"])
            destination = _parse_pointer(operation["path"])
            result = _copy(result, source, destination)
        elif op == "test":
            _require_keys(operation, ("path", "value"))
            path = _parse_pointer(operation["path"])
            result = _test(result, path, operation["value"])
        else:
            raise ValueError("unknown operation")

    return result


def _require_keys(operation, keys):
    for key in keys:
        if key not in operation:
            raise ValueError("missing operation key")


def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")

    if pointer == "":
        return []

    if not pointer.startswith("/"):
        raise ValueError("invalid pointer")

    tokens = []
    for raw_token in pointer[1:].split("/"):
        decoded = []
        i = 0
        while i < len(raw_token):
            ch = raw_token[i]
            if ch == "~":
                if i + 1 >= len(raw_token):
                    raise ValueError("invalid tilde escape")
                nxt = raw_token[i + 1]
                if nxt == "0":
                    decoded.append("~")
                elif nxt == "1":
                    decoded.append("/")
                else:
                    raise ValueError("invalid tilde escape")
                i += 2
            else:
                decoded.append(ch)
                i += 1
        tokens.append("".join(decoded))

    return tokens


def _parse_array_index(token):
    if token == "0":
        return 0
    if not token:
        raise ValueError("invalid array index")

    first = token[0]
    if first < "1" or first > "9":
        raise ValueError("invalid array index")

    for ch in token[1:]:
        if ch < "0" or ch > "9":
            raise ValueError("invalid array index")

    return int(token)


def _step(container, token):
    if isinstance(container, list):
        if token == "-":
            raise ValueError("invalid array index")
        index = _parse_array_index(token)
        if index >= len(container):
            raise ValueError("array index out of range")
        return container[index]

    if isinstance(container, dict):
        if token not in container:
            raise ValueError("missing target")
        return container[token]

    raise ValueError("cannot traverse scalar")


def _get(root, tokens):
    current = root
    for token in tokens:
        current = _step(current, token)
    return current


def _get_parent(root, tokens):
    current = root
    for token in tokens[:-1]:
        current = _step(current, token)
    return current


def _add(root, tokens, value):
    if not tokens:
        return copy.deepcopy(value)

    parent = _get_parent(root, tokens)
    last = tokens[-1]

    if isinstance(parent, list):
        if last == "-":
            parent.append(copy.deepcopy(value))
        else:
            index = _parse_array_index(last)
            if index > len(parent):
                raise ValueError("array index out of range")
            parent.insert(index, copy.deepcopy(value))
    elif isinstance(parent, dict):
        parent[last] = copy.deepcopy(value)
    else:
        raise ValueError("cannot add to scalar")

    return root


def _remove(root, tokens):
    if not tokens:
        raise ValueError("cannot remove root")

    parent = _get_parent(root, tokens)
    last = tokens[-1]

    if isinstance(parent, list):
        if last == "-":
            raise ValueError("invalid array index")
        index = _parse_array_index(last)
        if index >= len(parent):
            raise ValueError("array index out of range")
        del parent[index]
    elif isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing target")
        del parent[last]
    else:
        raise ValueError("cannot remove from scalar")

    return root


def _replace(root, tokens, value):
    if not tokens:
        return copy.deepcopy(value)

    parent = _get_parent(root, tokens)
    last = tokens[-1]

    if isinstance(parent, list):
        if last == "-":
            raise ValueError("invalid array index")
        index = _parse_array_index(last)
        if index >= len(parent):
            raise ValueError("array index out of range")
        parent[index] = copy.deepcopy(value)
    elif isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing target")
        parent[last] = copy.deepcopy(value)
    else:
        raise ValueError("cannot replace in scalar")

    return root


def _move(root, source_tokens, destination_tokens):
    source_value = _get(root, source_tokens)

    if source_tokens == destination_tokens:
        return root

    if _is_proper_descendant(destination_tokens, source_tokens):
        raise ValueError("cannot move into descendant")

    _remove(root, source_tokens)
    return _add(root, destination_tokens, source_value)


def _copy(root, source_tokens, destination_tokens):
    source_value = _get(root, source_tokens)
    return _add(root, destination_tokens, source_value)


def _test(root, tokens, value):
    target = _get(root, tokens)
    if not _json_equal(target, value):
        raise ValueError("test failed")
    return root


def _is_proper_descendant(descendant, ancestor):
    if len(descendant) <= len(ancestor):
        return False
    return descendant[:len(ancestor)] == ancestor


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if a is None or b is None:
        return a is None and b is None

    if isinstance(a, str) or isinstance(b, str):
        return isinstance(a, str) and isinstance(b, str) and a == b

    if isinstance(a, (int, float)) or isinstance(b, (int, float)):
        return (
            isinstance(a, (int, float))
            and isinstance(b, (int, float))
            and a == b
        )

    if isinstance(a, list) or isinstance(b, list):
        if not (isinstance(a, list) and isinstance(b, list)):
            return False
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    if isinstance(a, dict) or isinstance(b, dict):
        if not (isinstance(a, dict) and isinstance(b, dict)):
            return False
        if len(a) != len(b):
            return False
        for key, value in a.items():
            if key not in b:
                return False
            if not _json_equal(value, b[key]):
                return False
        return True

    return type(a) is type(b) and a == b

import heapq


class _MaxString:
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value

    def __lt__(self, other):
        return self.value > other.value


def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}

    for entry in migrations:
        if not isinstance(entry, dict):
            raise ValueError("migration entry must be a dictionary")
        if "id" not in entry:
            raise ValueError("migration entry missing id")
        migration_id = entry["id"]
        if not isinstance(migration_id, str):
            raise ValueError("migration id must be a string")
        if migration_id in registry:
            raise ValueError("duplicate migration id")

        if "deps" not in entry:
            raise ValueError("migration entry missing deps")
        raw_deps = entry["deps"]
        if not isinstance(raw_deps, list):
            raise ValueError("migration deps must be a list")

        deps = set()
        for dep in raw_deps:
            if not isinstance(dep, str):
                raise ValueError("migration dependency must be a string")
            deps.add(dep)

        if "reversible" not in entry:
            raise ValueError("migration entry missing reversible")
        reversible = entry["reversible"]
        if not isinstance(reversible, bool):
            raise ValueError("migration reversible must be a bool")

        registry[migration_id] = {
            "deps": deps,
            "reversible": reversible,
        }

    for migration_id, info in registry.items():
        for dep in info["deps"]:
            if dep not in registry:
                raise ValueError("unknown migration dependency")
            if dep == migration_id:
                raise ValueError("self dependency")

    dependents = {migration_id: set() for migration_id in registry}
    indegree = {}

    for migration_id, info in registry.items():
        deps = info["deps"]
        indegree[migration_id] = len(deps)
        for dep in deps:
            dependents[dep].add(migration_id)

    queue = [migration_id for migration_id, degree in indegree.items() if degree == 0]
    processed = 0

    while queue:
        migration_id = queue.pop()
        processed += 1
        for dependent in dependents[migration_id]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                queue.append(dependent)

    if processed != len(registry):
        raise ValueError("dependency cycle")

    def name_set(names):
        result = set()
        for name in names:
            if not isinstance(name, str):
                raise ValueError("migration name must be a string")
            if name not in registry:
                raise ValueError("unknown migration name")
            result.add(name)
        return result

    def dependency_closure(start):
        result = set(start)
        stack = list(start)
        while stack:
            migration_id = stack.pop()
            for dep in registry[migration_id]["deps"]:
                if dep not in result:
                    result.add(dep)
                    stack.append(dep)
        return result

    applied_set = name_set(applied)
    target_set = name_set(target)

    applied_closure = dependency_closure(applied_set)
    if not applied_closure.issubset(applied_set):
        raise ValueError("applied migrations are not dependency-closed")

    desired = dependency_closure(target_set)
    removal = applied_set - desired

    for migration_id in removal:
        if not registry[migration_id]["reversible"]:
            raise ValueError("required rollback is irreversible")

    current = set(applied_set)
    dependent_count = {migration_id: 0 for migration_id in removal}

    for migration_id in current:
        for dep in registry[migration_id]["deps"]:
            if dep in dependent_count:
                dependent_count[dep] += 1

    rollback_heap = []
    for migration_id, count in dependent_count.items():
        if count == 0:
            heapq.heappush(rollback_heap, _MaxString(migration_id))

    plan = []

    while rollback_heap:
        migration_id = heapq.heappop(rollback_heap).value
        plan.append("-" + migration_id)
        current.remove(migration_id)

        for dep in registry[migration_id]["deps"]:
            if dep in dependent_count:
                dependent_count[dep] -= 1
                if dependent_count[dep] == 0:
                    heapq.heappush(rollback_heap, _MaxString(dep))

    missing = desired - current
    forward_indegree = {}
    forward_heap = []

    for migration_id in missing:
        count = 0
        for dep in registry[migration_id]["deps"]:
            if dep in missing:
                count += 1
        forward_indegree[migration_id] = count
        if count == 0:
            heapq.heappush(forward_heap, migration_id)

    while forward_heap:
        migration_id = heapq.heappop(forward_heap)
        plan.append("+" + migration_id)

        for dependent in dependents[migration_id]:
            if dependent in forward_indegree:
                forward_indegree[dependent] -= 1
                if forward_indegree[dependent] == 0:
                    heapq.heappush(forward_heap, dependent)

    return plan

