class _MaxStr:
    __slots__ = ("s",)

    def __init__(self, s):
        self.s = s

    def __lt__(self, other):
        return self.s > other.s

    def __eq__(self, other):
        return self.s == other.s


def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    registry = {}
    for entry in migrations:
        mid = entry["id"]
        if mid in registry:
            raise ValueError("duplicate migration id")
        registry[mid] = {
            "deps": list(entry["deps"]),
            "reversible": entry["reversible"],
        }

    deps_unique = {}
    for mid, info in registry.items():
        seen = set()
        unique = []
        for dep in info["deps"]:
            if dep not in seen:
                seen.add(dep)
                unique.append(dep)
        deps_unique[mid] = unique

    for mid, deps in deps_unique.items():
        for dep in deps:
            if dep == mid:
                raise ValueError("self dependency")
            if dep not in registry:
                raise ValueError("unknown dependency")

    dependents = {mid: [] for mid in registry}
    indegree = {}
    for mid, deps in deps_unique.items():
        indegree[mid] = len(deps)
        for dep in deps:
            dependents[dep].append(mid)

    zero = [mid for mid, deg in indegree.items() if deg == 0]
    processed = 0
    while zero:
        mid = zero.pop()
        processed += 1
        for dependent in dependents[mid]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                zero.append(dependent)

    if processed != len(registry):
        raise ValueError("dependency cycle")

    applied_set = set(applied)
    target_set = set(target)

    for mid in applied_set:
        if mid not in registry:
            raise ValueError("unknown applied migration")
    for mid in target_set:
        if mid not in registry:
            raise ValueError("unknown target migration")

    for mid in applied_set:
        for dep in deps_unique[mid]:
            if dep not in applied_set:
                raise ValueError("applied migrations are not dependency-closed")

    desired = set(target_set)
    stack = list(target_set)
    while stack:
        mid = stack.pop()
        for dep in deps_unique[mid]:
            if dep not in desired:
                desired.add(dep)
                stack.append(dep)

    remove_set = applied_set - desired
    for mid in remove_set:
        if not registry[mid]["reversible"]:
            raise ValueError("irreversible migration must be removed")

    plan = []
    current_applied = set(applied_set)

    if remove_set:
        count = {mid: 0 for mid in remove_set}
        for mid in current_applied:
            for dep in deps_unique[mid]:
                if dep in remove_set:
                    count[dep] += 1

        heap = []
        for mid in remove_set:
            if count[mid] == 0:
                heapq.heappush(heap, _MaxStr(mid))

        remaining = set(remove_set)
        while remaining:
            if not heap:
                raise ValueError("cannot determine rollback order")
            item = heapq.heappop(heap)
            mid = item.s
            if mid not in remaining:
                continue
            plan.append("-" + mid)
            remaining.remove(mid)
            current_applied.remove(mid)
            for dep in deps_unique[mid]:
                if dep in remove_set:
                    count[dep] -= 1
                    if count[dep] == 0 and dep in remaining:
                        heapq.heappush(heap, _MaxStr(dep))

    missing = desired - current_applied
    if missing:
        dep_count = {}
        for mid in missing:
            c = 0
            for dep in deps_unique[mid]:
                if dep not in current_applied:
                    c += 1
            dep_count[mid] = c

        heap = []
        for mid in missing:
            if dep_count[mid] == 0:
                heapq.heappush(heap, mid)

        remaining = set(missing)
        while remaining:
            if not heap:
                raise ValueError("cannot determine forward order")
            mid = heapq.heappop(heap)
            if mid not in remaining:
                continue
            plan.append("+" + mid)
            remaining.remove(mid)
            current_applied.add(mid)
            for dependent in dependents[mid]:
                if dependent in remaining:
                    dep_count[dependent] -= 1
                    if dep_count[dependent] == 0:
                        heapq.heappush(heap, dependent)

    return plan

