        if not isinstance(op, str):
            raise ValueError("op must be a string")
        if op not in ("add", "remove", "replace", "move", "copy", "test"):
            raise ValueError("invalid op")

        if "path" not in operation:
            raise ValueError("missing path")
        path = operation["path"]
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        tokens = _parse_pointer(path)

        if op == "add":
            if "value" not in operation:
                raise ValueError("missing value")
            doc = _add(doc, tokens, operation["value"])

        elif op == "remove":
            _remove(doc, tokens)

        elif op == "replace":
            if "value" not in operation:
                raise ValueError("missing value")
            doc = _replace(doc, tokens, operation["value"])

        elif op == "move":
            if "from" not in operation:
                raise ValueError("missing from")
            from_path = operation["from"]
            if not isinstance(from_path, str):
                raise ValueError("from must be a string")
            from_tokens = _parse_pointer(from_path)

            _get(doc, from_tokens)

            if from_tokens == tokens:
                continue

            if len(tokens) > len(from_tokens) and tokens[:len(from_tokens)] == from_tokens:
                raise ValueError("cannot move into a descendant")

            removed = _remove(doc, from_tokens)
            doc = _add(doc, tokens, removed)

        elif op == "copy":
            if "from" not in operation:
                raise ValueError("missing from")
            from_path = operation["from"]
