            _test(doc, tokens, operation["value"])

    return doc


def _parse_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("pointer must start with /")
    return [_decode_token(part) for part in pointer.split("/")[1:]]


def _decode_token(token):
    if "~" not in token:
        return token

    result = []
    i = 0
    n = len(token)
    while i < n:
        ch = token[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError("invalid escape")
            nxt = token[i + 1]
            if nxt == "0":
                result.append("~")
            elif nxt == "1":
                result.append("/")
            else:
                raise ValueError("invalid escape")
            i += 2
        else:
            result.append(ch)
            i += 1
    return "".join(result)


def _parse_index(token):
    if not token:
        raise ValueError("invalid array index")
    if token == "0":
        return 0
    if token[0] < "1" or token[0] > "9":
        raise ValueError("invalid array index")
    for ch in token[1:]:
        if ch < "0" or ch > "9":
            raise ValueError("invalid array index")
    try:
        return int(token)
    except ValueError:
        raise ValueError("invalid array index")


def _resolve_parent(doc, tokens):
    parent = doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            if token not in parent:
                raise ValueError("missing target")
            parent = parent[token]
        elif isinstance(parent, list):
            index = _parse_index(token)
            if index >= len(parent):
                raise ValueError("index out of range")
            parent = parent[index]
        else:
            raise ValueError("cannot traverse scalar")
    return parent


def _get(doc, tokens):
