    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise ValueError("missing target")
            current = current[token]
        elif isinstance(current, list):
            index = _parse_index(token)
            if index >= len(current):
                raise ValueError("index out of range")
            current = current[index]
        else:
            raise ValueError("cannot traverse scalar")
    return current


def _add(doc, tokens, value):
    if not tokens:
        return _deepcopy_json(value)

    parent = _resolve_parent(doc, tokens)
    last = tokens[-1]

    if isinstance(parent, dict):
        parent[last] = _deepcopy_json(value)
    elif isinstance(parent, list):
        if last == "-":
            parent.append(_deepcopy_json(value))
        else:
            index = _parse_index(last)
            if index > len(parent):
                raise ValueError("index out of range")
            parent.insert(index, _deepcopy_json(value))
    else:
        raise ValueError("cannot add to scalar")

    return doc


def _replace(doc, tokens, value):
