def _deepcopy_json(value):
    if isinstance(value, dict):
        root = {}
        stack = [(value, root)]
    elif isinstance(value, list):
        root = [None] * len(value)
        stack = [(value, root)]
    else:
        return value

    while stack:
        src, dst = stack.pop()

        if isinstance(src, dict):
            for key, item in src.items():
                if isinstance(item, dict):
                    new_item = {}
                    dst[key] = new_item
                    stack.append((item, new_item))
                elif isinstance(item, list):
                    new_item = [None] * len(item)
                    dst[key] = new_item
                    stack.append((item, new_item))
                else:
                    dst[key] = item
        else:
            for index, item in enumerate(src):
                if isinstance(item, dict):
                    new_item = {}
                    dst[index] = new_item
                    stack.append((item, new_item))
                elif isinstance(item, list):
                    new_item = [None] * len(item)
                    dst[index] = new_item
                    stack.append((item, new_item))
                else:
                    dst[index] = item

    return root


def _json_equal(a, b):
    stack = [(a, b)]

    while stack:
        x, y = stack.pop()

        if isinstance(x, bool) or isinstance(y, bool):
            if not (isinstance(x, bool) and isinstance(y, bool) and x == y):
                return False
            continue

        if isinstance(x, (int, float)) and isinstance(y, (int, float)):
            if x != y:
                return False
            continue

        if x is None or y is None:
            if not (x is None and y is None):
                return False
            continue

        if isinstance(x, str) or isinstance(y, str):
            if not (isinstance(x, str) and isinstance(y, str) and x == y):
                return False
            continue

        if isinstance(x, list) or isinstance(y, list):
            if not (isinstance(x, list) and isinstance(y, list)):
                return False
            if len(x) != len(y):
                return False
            for i in range(len(x)):
                stack.append((x[i], y[i]))
            continue

        if isinstance(x, dict) or isinstance(y, dict):
            if not (isinstance(x, dict) and isinstance(y, dict)):
                return False
            if len(x) != len(y):
                return False
            for key, value in x.items():
                if key not in y:
                    return False
                stack.append((value, y[key]))
            continue

        if type(x) is not type(y) or x != y:
            return False

    return True
