def run_cache(capacity: int, operations: list[dict]) -> list:
    entries = OrderedDict()
    expiry_heap = []
    results = []
    cap = capacity

    def purge(now: int) -> None:
        while expiry_heap and expiry_heap[0][0] <= now:
            expires_at, key = heapq.heappop(expiry_heap)
            item = entries.get(key)
            if item is not None and item[1] == expires_at:
                del entries[key]

    for operation in operations:
        t = operation["t"]
        purge(t)

        kind = operation["op"]

        if kind == "put":
            key = operation["key"]
            value = operation["value"]
            ttl = operation["ttl"]

            if ttl <= 0 or cap == 0:
                if key in entries:
                    del entries[key]
                results.append(None)
            else:
                expires_at = t + ttl
                if key in entries:
                    del entries[key]
                entries[key] = (value, expires_at)
                heapq.heappush(expiry_heap, (expires_at, key))

                while len(entries) > cap:
                    entries.popitem(last=False)

                results.append(None)

        elif kind == "get":
            key = operation["key"]
            item = entries.get(key)
            if item is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(item[0])

        elif kind == "delete":
            key = operation["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)

        elif kind == "items":
            results.append([[key, item[0]] for key, item in entries.items()])

        elif kind == "resize":
            cap = operation["capacity"]
            while len(entries) > cap:
                entries.popitem(last=False)
            results.append(None)

    return results

