        if not isinstance(duration, int) or duration <= 0:
            raise ValueError("duration must be a positive integer")

        priority = job["priority"]
        if not isinstance(priority, int):
            raise ValueError("priority must be an integer")

        info[jid] = (duration, priority, unique_deps)

    indegree = {jid: len(info[jid][2]) for jid in id_set}
    dependents = {jid: [] for jid in id_set}

    for jid, (_, _, deps) in info.items():
        for dep in deps:
            dependents[dep].append(jid)

    queue = deque(jid for jid in id_set if indegree[jid] == 0)
    processed = 0

    while queue:
        jid = queue.popleft()
        processed += 1
        for dep_jid in dependents[jid]:
            indegree[dep_jid] -= 1
            if indegree[dep_jid] == 0:
                queue.append(dep_jid)

