from collections import deque

def plan_migrations(applied: list[str], target: list[str], migrations: list[dict]) -> list[str]:
    # ---- Validate entire registry ----
    ids = set()
    raw_deps = {}
    reversible = {}
    for m in migrations:
        mid = m["id"]
        if not isinstance(mid, str):
            raise ValueError("invalid id")
        if mid in ids:
            raise ValueError("duplicate id: %r" % (mid,))
        ids.add(mid)
        raw_deps[mid] = list(m["deps"])
        reversible[mid] = bool(m["reversible"])

    deps = {}
    for mid in ids:
        ds = set()
        for d in raw_deps[mid]:
            if not isinstance(d, str):
                raise ValueError("invalid dependency")
            if d == mid:
                raise ValueError("self dependency: %r" % (mid,))
            if d not in ids:
                raise ValueError("unknown dependency: %r" % (d,))
            ds.add(d)
        deps[mid] = ds

    # Cycle detection (Kahn's algorithm)
    indeg = {x: len(deps[x]) for x in ids}
    adj = {x: [] for x in ids}
    for x in ids:
        for d in deps[x]:
            adj[d].append(x)
    q = deque(x for x in ids if indeg[x] == 0)
    seen_count = 0
    while q:
        x = q.popleft()
        seen_count += 1
        for y in adj[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                q.append(y)
    if seen_count != len(ids):
        raise ValueError("dependency cycle detected")

    # ---- Validate applied / target names ----
    applied_set = set()
    for a in applied:
        if a not in ids:
            raise ValueError("unknown applied migration: %r" % (a,))
        applied_set.add(a)

    target_set = set()
    for t in target:
        if t not in ids:
            raise ValueError("unknown target migration: %r" % (t,))
        target_set.add(t)

    # ---- applied must be dependency-closed ----
    for a in applied_set:
        for d in deps[a]:
            if d not in applied_set:
                raise ValueError("applied set not dependency-closed")

    # ---- Desired = target + transitive dependency closure ----
    desired = set()
    stack = list(target_set)
    while stack:
        x = stack.pop()
        if x in desired:
            continue
        desired.add(x)
        for d in deps[x]:
            if d not in desired:
                stack.append(d)

    to_remove = applied_set - desired

    # ---- Every required removal must be reversible ----
    for x in to_remove:
        if not reversible[x]:
            raise ValueError("cannot roll back irreversible migration: %r" % (x,))

    plan = []

    # ---- Deterministic rollback ----
    current = set(applied_set)
    removal = set(to_remove)
    while removal:
        blocked = set()
        for y in current:
            for d in deps[y]:
                if d in current:
                    blocked.add(d)
        candidates = [x for x in removal if x not in blocked]
        # A DAG guarantees at least one candidate exists.
        pick = max(candidates)
        plan.append("-" + pick)
        removal.remove(pick)
        current.remove(pick)

    # ---- Deterministic forward application ----
    missing = desired - current
    while missing:
        candidates = [x for x in missing if all(d in current for d in deps[x])]
        pick = min(candidates)
        plan.append("+" + pick)
        missing.remove(pick)
        current.add(pick)

    return plan
