            if token == _STAR:
                star = pi
                star_match = ti
                pi += 1
                continue

        if star != -1:
            pi = star + 1
            star_match += 1
            ti = star_match
            continue

        return False

    while pi < m and tokens[pi] == _STAR:
        pi += 1

