def path_glob(pattern: str, path: str) -> bool:
    if pattern == "":
        pattern_segments = []
    else:
        if pattern[0] == "/" or pattern[-1] == "/" or "//" in pattern:
            raise ValueError("invalid pattern")

        raw_segments = pattern.split("/")
        pattern_segments = []

        for segment in raw_segments:
            if segment == "":
                raise ValueError("invalid pattern")

            if segment == "**":
                pattern_segments.append(None)
                continue

            tokens = _parse_segment(segment)

            if any(token < 0 for token in tokens):
                pattern_segments.append((tokens, None))
            else:
                literal = "".join(chr(token) for token in tokens)
                pattern_segments.append((None, literal))

    path_segments = [] if path == "" else path.split("/")
    path_count = len(path_segments)

    reachable = [0]

    for segment in pattern_segments:
        if not reachable:
            return False

        if segment is None:
            start = reachable[0]
            reachable = range(start, path_count + 1)
            continue

        tokens, literal = segment
        next_reachable = []

        if literal is not None:
            for index in reachable:
                if index < path_count and path_segments[index] == literal:
                    next_reachable.append(index + 1)
        else:
            for index in reachable:
                if index < path_count and _match_segment(tokens, path_segments[index]):
                    next_reachable.append(index + 1)

        reachable = next_reachable

    if not reachable:
        return False

    if isinstance(reachable, range):
        return path_count in reachable

    return reachable[-1] == path_count
