import heapq
from collections import OrderedDict

def run_cache(capacity: int, operations: list[dict]) -> list:
    cap = capacity
    entries = OrderedDict()  # key -> (value, version)
    expiry_heap = []  # (expires_at, version, key)
    version = 0
    results = []

    for op in operations:
        t = op["t"]

        while expiry_heap and expiry_heap[0][0] <= t:
            exp, ver, key = heapq.heappop(expiry_heap)
            ent = entries.get(key)
            if ent is not None and ent[1] == ver:
                del entries[key]

        typ = op["op"]

        if typ == "put":
            key = op["key"]
            value = op["value"]
            ttl = op["ttl"]

            if ttl <= 0 or cap == 0:
                if key in entries:
                    del entries[key]
                results.append(None)
            else:
                version += 1
                exp = t + ttl
                entries[key] = (value, version)
                entries.move_to_end(key)
                heapq.heappush(expiry_heap, (exp, version, key))

                while len(entries) > cap:
                    entries.popitem(last=False)

                results.append(None)

        elif typ == "get":
            key = op["key"]
            ent = entries.get(key)
            if ent is None:
                results.append(None)
            else:
                entries.move_to_end(key)
                results.append(ent[0])

        elif typ == "delete":
            key = op["key"]
            if key in entries:
                del entries[key]
                results.append(True)
            else:
                results.append(False)

        elif typ == "items":
            results.append([[k, v[0]] for k, v in entries.items()])

        elif typ == "resize":
            cap = op["capacity"]
            while len(entries) > cap:
                entries.popitem(last=False)
            results.append(None)

    return results

