import re

def _tokenize_segment(seg: str):
    tokens = []
    i = 0
    n = len(seg)
    while i < n:
        c = seg[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash in pattern segment")
            tokens.append(('lit', seg[i + 1]))
            i += 2
        elif c == '*':
            tokens.append(('star', None))
            i += 1
        elif c == '?':
            tokens.append(('q', None))
            i += 1
        else:
            tokens.append(('lit', c))
            i += 1
    return tokens


def _match_segment(tokens, s: str) -> bool:
    ti = 0
    si = 0
    nt = len(tokens)
    ns = len(s)
    star_ti = -1
    star_si = -1

    while si < ns:
        if ti < nt:
            kind, val = tokens[ti]
            if kind == 'q':
                ti += 1
                si += 1
                continue
            if kind == 'lit' and val == s[si]:
                ti += 1
                si += 1
                continue
            if kind == 'star':
                star_ti = ti
                star_si = si
                ti += 1
                continue

        if star_ti != -1:
            star_si += 1
            si = star_si
            ti = star_ti + 1
        else:
            return False

    while ti < nt and tokens[ti][0] == 'star':
        ti += 1
    return ti == nt


def path_glob(pattern: str, path: str) -> bool:
    # Parse and validate the entire pattern first.
    if pattern == "":
        pat_segs = []
    else:
        raw_segs = pattern.split('/')
        pat_segs = []
        for raw in raw_segs:
            if raw == "":
                raise ValueError("invalid pattern: empty segment")
            if raw == "**":
                pat_segs.append(None)  # special multi-segment wildcard
            else:
                tokens = _tokenize_segment(raw)
                pat_segs.append(tokens)

    path_segs = path.split('/') if path else []

    # Greedy matching over segments, with backtracking for '**'.
    pi = 0
    si = 0
    np = len(pat_segs)
    ns = len(path_segs)
    star_pi = -1
    star_si = -1

    while si < ns:
        if pi < np:
            seg = pat_segs[pi]
            if seg is None:
                star_pi = pi
                star_si = si
                pi += 1
                continue
            if _match_segment(seg, path_segs[si]):
                pi += 1
                si += 1
                continue

        if star_pi != -1:
            star_si += 1
            si = star_si
            pi = star_pi + 1
        else:
            return False

    while pi < np and pat_segs[pi] is None:
        pi += 1

    return pi == np
